import { useEffect, useState, useCallback, useMemo } from 'react';
import { useWindowAPI } from '../../hooks/useWindowAPI';
import { useWindowStore } from '../../store';
import { TerminalTabBar } from './components/TerminalTabBar';
import { TerminalSession, type TerminalTabState } from './components/TerminalSession';
import { TerminalMenu } from './components/TerminalMenu';
import { TerminalSearch } from './components/TerminalSearch';
import { TerminalAboutDialog } from './components/TerminalAboutDialog';
import { useTerminalProfileStore } from './store/useTerminalProfileStore';
import { themes } from './themes';
import './Terminal.css';

interface TerminalProps {
  windowId: string;
}

const generateId = () => Math.random().toString(36).substr(2, 9);

export function Terminal({ windowId }: TerminalProps) {
  const { updateState, getState } = useWindowAPI(windowId);
  const isFocused = useWindowStore((s) => s.windows.find(w => w.id === windowId)?.isFocused);

  // Read state once on mount to initialize local tabs state
  const initialAppState = useMemo(() => getState<any>() || {}, [getState]);

  // We manage tabs and activeTabId locally for performance, then sync to windowStore occasionally
  const [tabs, setTabs] = useState<TerminalTabState[]>(() => {
    if (initialAppState.tabs && initialAppState.tabs.length > 0) {
      return initialAppState.tabs;
    }
    // Migrate legacy state or create default
    const effectiveUser = initialAppState.effectiveUser || 'peasant';
    const defaultHomeId = effectiveUser === 'root' ? 'root-home' : `home-${effectiveUser}`;
    const defaultHomePath = effectiveUser === 'root' ? '/root' : `/home/${effectiveUser}`;
    return [{
      id: `tab-${generateId()}`,
      title: initialAppState.cwdPath ? (initialAppState.cwdPath === '/' ? '/' : initialAppState.cwdPath.split('/').pop()) : '~',
      cwdId: initialAppState.cwdId || defaultHomeId,
      cwdPath: initialAppState.cwdPath || defaultHomePath,
      effectiveUser: effectiveUser,
      commandHistory: initialAppState.commandHistory || [],
      interactiveApp: initialAppState.interactiveApp,
      nanoFileId: initialAppState.nanoFileId,
      hasShownMotd: initialAppState.hasShownMotd || false,
    }];
  });

  const [activeTabId, setActiveTabId] = useState<string>(
    initialAppState.activeTabId || (tabs[0]?.id || '')
  );

  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [isAboutOpen, setIsAboutOpen] = useState(false);

  const profile = useTerminalProfileStore(state => state.activeProfile);
  const theme = themes[profile.colorScheme] || themes['ubuntu'];

  // Sync state to window manager periodically or on unmount
  useEffect(() => {
    const activeTab = tabs.find(t => t.id === activeTabId);
    let windowTitle = 'Terminal';

    if (activeTab) {
      const hostname = localStorage.getItem('ubuntu-hostname') || 'envyy';
      let displayPath = activeTab.cwdPath;
      const homePrefix = `/home/${activeTab.effectiveUser}`;
      if (displayPath.startsWith(homePrefix)) {
        displayPath = '~' + displayPath.slice(homePrefix.length);
      }
      windowTitle = `${activeTab.effectiveUser}@${hostname}: ${displayPath}`;
    }

    updateState({ 
      tabs, 
      activeTabId,
      title: windowTitle,
      isLightTheme: profile.colorScheme === 'ubuntuLight'
    });
  }, [tabs, activeTabId, profile.colorScheme, updateState]);

  const handleTabStateChange = useCallback((tabId: string, updates: Partial<TerminalTabState>) => {
    setTabs(prev => prev.map(t => t.id === tabId ? { ...t, ...updates } : t));
  }, []);

  const handleAddTab = useCallback(() => {
    const newTabId = `tab-${generateId()}`;
    const activeTab = tabs.find(t => t.id === activeTabId);

    const user = activeTab ? activeTab.effectiveUser : 'peasant';
    const defaultHomeId = user === 'root' ? 'root-home' : `home-${user}`;
    const defaultHomePath = user === 'root' ? '/root' : `/home/${user}`;

    const newTab: TerminalTabState = {
      id: newTabId,
      title: '~', // Will be updated on first prompt
      cwdId: activeTab ? activeTab.cwdId : defaultHomeId,
      cwdPath: activeTab ? activeTab.cwdPath : defaultHomePath,
      effectiveUser: user,
      commandHistory: activeTab ? [...activeTab.commandHistory] : [],
      hasShownMotd: true, // Don't show MOTD on new tabs
    };

    setTabs(prev => [...prev, newTab]);
    setActiveTabId(newTabId);
  }, [tabs, activeTabId]);

  const handleCloseTab = useCallback((tabId: string) => {
    setTabs(prev => {
      const newTabs = prev.filter(t => t.id !== tabId);
      if (newTabs.length === 0) {
        useWindowStore.getState().closeWindow(windowId);
        return prev;
      }
      if (activeTabId === tabId) {
        // Find index of closed tab
        const idx = prev.findIndex(t => t.id === tabId);
        // Switch to the one before it, or after if it was the first
        const nextActive = newTabs[idx - 1] || newTabs[0];
        setActiveTabId(nextActive.id);
      }
      return newTabs;
    });
  }, [activeTabId, windowId]);

  useEffect(() => {
    const handleNewTab = (e: any) => {
      if (e.detail?.windowId === windowId) {
        handleAddTab();
      }
    };

    const handleToggleSearch = (e: any) => {
      if (e.detail?.windowId === windowId) {
        setIsSearchOpen(prev => !prev);
      }
    };

    const handleFullscreen = (e: any) => {
      if (e.detail?.windowId === windowId) {
        useWindowStore.getState().toggleMaximize(windowId);
      }
    };

    const handleAbout = (e: any) => {
      if (e.detail?.windowId === windowId) {
        setIsAboutOpen(true);
      }
    };

    window.addEventListener('terminal:new-tab', handleNewTab);
    window.addEventListener('terminal:toggle-search', handleToggleSearch);
    window.addEventListener('terminal:fullscreen', handleFullscreen);
    window.addEventListener('terminal:about', handleAbout);

    return () => {
      window.removeEventListener('terminal:new-tab', handleNewTab);
      window.removeEventListener('terminal:toggle-search', handleToggleSearch);
      window.removeEventListener('terminal:fullscreen', handleFullscreen);
      window.removeEventListener('terminal:about', handleAbout);
    };
  }, [windowId, handleAddTab]);

  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (e.ctrlKey && e.shiftKey && e.key === 'T') {
      e.preventDefault();
      handleAddTab();
    }
    else if (e.ctrlKey && e.shiftKey && e.key === 'W') {
      e.preventDefault();
      handleCloseTab(activeTabId);
    }
    else if (e.ctrlKey && e.key === 'PageUp') {
      e.preventDefault();
      const idx = tabs.findIndex(t => t.id === activeTabId);
      if (idx > 0) setActiveTabId(tabs[idx - 1].id);
      else setActiveTabId(tabs[tabs.length - 1].id); // loop
    }
    else if (e.ctrlKey && e.key === 'PageDown') {
      e.preventDefault();
      const idx = tabs.findIndex(t => t.id === activeTabId);
      if (idx < tabs.length - 1) setActiveTabId(tabs[idx + 1].id);
      else setActiveTabId(tabs[0].id); // loop
    }
    else if (e.altKey && !isNaN(Number(e.key))) {
      const num = Number(e.key);
      if (num >= 1 && num <= tabs.length) {
        e.preventDefault();
        setActiveTabId(tabs[num - 1].id);
      }
    }
  }, [tabs, activeTabId, handleAddTab, handleCloseTab]);

  return (
    <div 
      className="terminal-app" 
      style={{ 
        '--term-bg': theme.background,
        '--term-fg': theme.foreground,
        '--term-chrome': theme.chrome,
        '--term-chrome-fg': theme.chromeForeground,
        backgroundColor: theme.background, 
        display: 'flex', 
        flexDirection: 'column', 
        width: '100%', 
        height: '100%', 
        outline: 'none', 
        padding: 0 
      } as React.CSSProperties}
      onKeyDown={handleKeyDown}
      tabIndex={-1} // Allow div to receive keyboard events
    >

      {/* Tab Bar */}
      {tabs.length > 1 && (
        <TerminalTabBar 
          tabs={tabs} 
          activeTabId={activeTabId} 
          onTabSelect={setActiveTabId} 
          onTabClose={handleCloseTab} 
          onTabAdd={handleAddTab}
        />
      )}

      {/* Settings button is now in TerminalHeaderControls */}

      {/* Terminal Sessions */}
      <div style={{ flex: 1, position: 'relative', display: 'flex', overflow: 'hidden' }}>
        {tabs.map(tab => (
          <TerminalSession 
            key={tab.id}
            windowId={windowId}
            tab={tab}
            isActive={tab.id === activeTabId}
            isFocused={isFocused || false}
            onStateChange={handleTabStateChange}
            onTabClose={handleCloseTab}
          />
        ))}
      </div>

      {/* Search Bar */}
      {isSearchOpen && (
        <TerminalSearch 
          windowId={windowId} 
          onClose={() => {
            setIsSearchOpen(false);
            window.dispatchEvent(new CustomEvent('terminal:close-search', { detail: { windowId } }));
          }} 
        />
      )}

      {/* About Dialog */}
      {isAboutOpen && <TerminalAboutDialog onClose={() => setIsAboutOpen(false)} />}
    </div>
  );
}

export function TerminalHeaderControls({ windowId }: { windowId: string }) {
  const appState = useWindowStore(state => state.windows.find(w => w.id === windowId)?.appState as any);

  const activeTabId = appState?.activeTabId;
  const tabs = appState?.tabs || [];
  const activeTab = tabs.find((t: any) => t.id === activeTabId) || tabs[0];

  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const user = activeTab?.effectiveUser || 'peasant';
  const homePath = user === 'root' ? '/root' : `/home/${user}`;
  const fullPath = activeTab?.cwdPath || homePath;
  const basename = fullPath === '/' ? '/' : (fullPath.split('/').pop() || '~');

  // Custom event trigger for new tab (this would ideally interact with Terminal component)
  // For now we'll just dispatch a dummy event, but full implementation would need context
  // The terminal adds a tab via a global event or store method if needed, but since we just want visual:

  return (
    <div className="terminal-header-csd">
      <div className="terminal-header-left">
        <button 
          className="terminal-header-btn" 
          title="New Tab" 
          onClick={() => {
            window.dispatchEvent(new CustomEvent('terminal:new-tab', { detail: { windowId } }));
          }}
          onDoubleClick={(e) => e.stopPropagation()}
        >
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line></svg>
        </button>
      </div>

      <div className="terminal-header-center">
        <div className="terminal-header-title">{user}@envyy: {basename}</div>
      </div>

      <div className="terminal-header-right">
        <button 
          className="terminal-header-btn" 
          title="Search" 
          onClick={() => window.dispatchEvent(new CustomEvent('terminal:toggle-search', { detail: { windowId } }))}
          onDoubleClick={(e) => e.stopPropagation()}
        >
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="11" cy="11" r="8"></circle><line x1="21" y1="21" x2="16.65" y2="16.65"></line></svg>
        </button>
        <div style={{ position: 'relative' }}>
          <button 
            className="terminal-header-btn" 
            title="Terminal Menu" 
            onClick={() => setIsMenuOpen(!isMenuOpen)}
            onDoubleClick={(e) => e.stopPropagation()}
          >
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="3" y1="12" x2="21" y2="12"></line><line x1="3" y1="6" x2="21" y2="6"></line><line x1="3" y1="18" x2="21" y2="18"></line></svg>
          </button>
          {isMenuOpen && <TerminalMenu windowId={windowId} onClose={() => setIsMenuOpen(false)} />}
        </div>
      </div>
    </div>
  );
}

import type { CommandHandler } from './types';
import { PACKAGE_DB, isPackageInstalled, installPackage, removePackage, getInstalledPackages } from '../packageDb';
import { parseArgs } from '../commandParser';

export const apt: CommandHandler = async (args, env, streams) => {
  if (args.length === 0) {
    streams.stderr.writeLine('apt: no command provided');
    return 1;
  }

  const subCommand = args[0];
  const pkgArgs = args.slice(1);
  const isRoot = env.effectiveUser === 'root';

  if (subCommand === 'update') {
    if (!isRoot) {
      streams.stderr.writeLine('E: Could not open lock file /var/lib/apt/lists/lock - open (13: Permission denied)');
      streams.stderr.writeLine('E: Unable to lock directory /var/lib/apt/lists/');
      return 100;
    }

    const lines = [
      'Hit:1 http://archive.ubuntu.com/ubuntu noble InRelease',
      'Hit:2 http://archive.ubuntu.com/ubuntu noble-updates InRelease',
      'Hit:3 http://archive.ubuntu.com/ubuntu noble-security InRelease',
      'Hit:4 http://ppa.launchpadcontent.net/deadsnakes/ppa/ubuntu noble InRelease',
      'Reading package lists... Done',
      'Building dependency tree... Done',
      'Reading state information... Done',
      "4 packages can be upgraded. Run 'apt list --upgradable' to see them. "
    ];

    for (const line of lines) {
      if (env.abortSignal?.aborted) return 130;
      streams.stdout.writeLine(line);
      await new Promise(r => setTimeout(r, 200 + Math.random() * 300));
    }
    return 0;
  }

  if (subCommand === 'install') {
    if (!isRoot) {
      streams.stderr.writeLine('E: Could not open lock file /var/lib/dpkg/lock-frontend - open (13: Permission denied)');
      streams.stderr.writeLine('E: Unable to acquire the dpkg frontend lock (/var/lib/dpkg/lock-frontend), are you root?');
      return 100;
    }

    if (pkgArgs.length === 0) {
      streams.stderr.writeLine('E: No packages found');
      return 100;
    }

    const toInstall = pkgArgs.filter(p => !p.startsWith('-'));
    let found = [];
    let notFound = [];

    for (const p of toInstall) {
      const pkg = PACKAGE_DB.find(dbPkg => dbPkg.name === p);
      if (pkg) found.push(pkg);
      else notFound.push(p);
    }

    if (notFound.length > 0) {
      streams.stderr.writeLine(`E: Unable to locate package ${notFound[0]}`);
      return 100;
    }

    const actuallyInstalling = found.filter(p => !isPackageInstalled(p.name));

    streams.stdout.writeLine('Reading package lists... Done');
    streams.stdout.writeLine('Building dependency tree... Done');
    streams.stdout.writeLine('Reading state information... Done');

    if (actuallyInstalling.length === 0) {
      streams.stdout.writeLine(`${found[0].name} is already the newest version (${found[0].version}).`);
      streams.stdout.writeLine('0 upgraded, 0 newly installed, 0 to remove and 4 not upgraded.');
      return 0;
    }

    streams.stdout.writeLine('The following NEW packages will be installed:');
    streams.stdout.writeLine('  ' + actuallyInstalling.map(p => p.name).join(' '));
    streams.stdout.writeLine(`0 upgraded, ${actuallyInstalling.length} newly installed, 0 to remove and 4 not upgraded.`);
    streams.stdout.writeLine('Need to get 36.4 kB of archives.');
    streams.stdout.writeLine('After this operation, 152 kB of additional disk space will be used.');

    for (let i = 0; i < actuallyInstalling.length; i++) {
      if (env.abortSignal?.aborted) return 130;
      const pkg = actuallyInstalling[i];
      streams.stdout.writeLine(`Get:${i+1} http://archive.ubuntu.com/ubuntu noble/${pkg.section.split('/')[0]} amd64 ${pkg.name} all ${pkg.version} [36.4 kB]`);
      await new Promise(_r => setTimeout(_r, 400));
    }

    streams.stdout.writeLine('Fetched 36.4 kB in 0s (234 kB/s)');

    for (const pkg of actuallyInstalling) {
      if (env.abortSignal?.aborted) return 130;
      streams.stdout.writeLine(`Selecting previously unselected package ${pkg.name}.`);
      streams.stdout.writeLine('(Reading database ... 245823 files and directories currently installed.)');
      streams.stdout.writeLine(`Preparing to unpack .../${pkg.name}_${pkg.version}_all.deb ...`);
      await new Promise(_r => setTimeout(_r, 300));
      streams.stdout.writeLine(`Unpacking ${pkg.name} (${pkg.version}) ...`);
      await new Promise(_r => setTimeout(_r, 300));
      streams.stdout.writeLine(`Setting up ${pkg.name} (${pkg.version}) ...`);

      installPackage(pkg.name);

      // We also need to reload dynamic commands in the current session.
      // Easiest is to emit an event or just do it in index.ts via a global mechanism.
      // In a real scenario, the command registry would be reloaded. We'll handle this in index.ts
    }

    streams.stdout.writeLine('Processing triggers for man-db (2.12.0-4build2) ...');

    // Quick hack to force dynamic load
    const { loadDynamicCommands } = await import('./index');
    await loadDynamicCommands();

    return 0;
  }

  if (subCommand === 'remove') {
    if (!isRoot) {
      streams.stderr.writeLine('E: Could not open lock file /var/lib/dpkg/lock-frontend - open (13: Permission denied)');
      return 100;
    }

    const toRemove = pkgArgs.filter(p => !p.startsWith('-'));
    if (toRemove.length === 0) return 0;

    const target = toRemove[0];
    if (!isPackageInstalled(target)) {
      streams.stderr.writeLine(`Package '${target}' is not installed, so not removed`);
      return 0;
    }

    streams.stdout.writeLine('Reading package lists... Done');
    streams.stdout.writeLine('Building dependency tree... Done');
    streams.stdout.writeLine('Reading state information... Done');
    streams.stdout.writeLine('The following packages will be REMOVED:');
    streams.stdout.writeLine('  ' + target);
    streams.stdout.writeLine('0 upgraded, 0 newly installed, 1 to remove and 4 not upgraded.');
    streams.stdout.writeLine('After this operation, 152 kB disk space will be freed.');
    streams.stdout.writeLine('(Reading database ... 245823 files and directories currently installed.)');

    await new Promise(_r => setTimeout(_r, 500));
    streams.stdout.writeLine(`Removing ${target} ...`);

    removePackage(target);
    const { loadDynamicCommands } = await import('./index');
    await loadDynamicCommands();

    return 0;
  }

  if (subCommand === 'list') {
    const { flags } = parseArgs(args);
    streams.stdout.writeLine('Listing...');

    if (flags.installed) {
      const installed = getInstalledPackages();
      for (const name of installed) {
        const p = PACKAGE_DB.find(db => db.name === name);
        if (p) {
          streams.stdout.writeLine(`${p.name}/${p.section.split('/')[0]} ${p.version} [installed]`);
        } else {
          streams.stdout.writeLine(`${name}/unknown unknown [installed]`);
        }
      }
    } else if (flags.upgradable) {
      streams.stdout.writeLine('bash/noble-updates 5.2.15-2ubuntu1.1 amd64 [upgradable from: 5.2.15-2ubuntu1]');
      streams.stdout.writeLine('coreutils/noble-updates 9.4-3ubuntu1.1 amd64 [upgradable from: 9.4-3ubuntu1]');
    } else {
      for (const p of PACKAGE_DB) {
        streams.stdout.writeLine(`${p.name}/${p.section.split('/')[0]} ${p.version} ${isPackageInstalled(p.name) ? '[installed]' : ''}`.trim());
      }
    }
    return 0;
  }

  if (subCommand === 'search') {
    const query = pkgArgs[0]?.toLowerCase();
    if (!query) return 0;

    for (const p of PACKAGE_DB) {
      if (p.name.includes(query) || p.description.toLowerCase().includes(query)) {
        streams.stdout.writeLine(`\x1b[32m${p.name}\x1b[0m - ${p.description}`);
      }
    }
    return 0;
  }

  if (subCommand === 'show') {
    const query = pkgArgs[0];
    if (!query) return 0;
    const p = PACKAGE_DB.find(db => db.name === query);
    if (!p) {
      streams.stderr.writeLine(`N: Unable to locate package ${query}`);
      return 100;
    }

    streams.stdout.writeLine(`Package: ${p.name}`);
    streams.stdout.writeLine(`Version: ${p.version}`);
    streams.stdout.writeLine(`Priority: optional`);
    streams.stdout.writeLine(`Section: ${p.section}`);
    streams.stdout.writeLine(`Maintainer: Ubuntu Developers`);
    streams.stdout.writeLine(`Installed-Size: ${p.installedSize}`);
    if (p.depends) streams.stdout.writeLine(`Depends: ${p.depends.join(', ')}`);
    streams.stdout.writeLine(`Description: ${p.description.replace('\n', '\n ')}`);
    return 0;
  }

  if (subCommand === 'upgrade') {
    streams.stdout.writeLine('Reading package lists... Done');
    streams.stdout.writeLine('Building dependency tree... Done');
    streams.stdout.writeLine('Reading state information... Done');
    streams.stdout.writeLine('Calculating upgrade... Done');
    streams.stdout.writeLine('0 upgraded, 0 newly installed, 0 to remove and 0 not upgraded.');
    return 0;
  }

  streams.stderr.writeLine(`E: Invalid operation ${subCommand}`);
  return 100;
};

export const aptGet: CommandHandler = (args, _env, streams) => apt(args, _env, streams);

export const dpkg: CommandHandler = (args, _env, streams) => {
  const { flags } = parseArgs(args, ['l']);

  if (flags.l) {
    streams.stdout.writeLine('Desired=Unknown/Install/Remove/Purge/Hold');
    streams.stdout.writeLine('| Status=Not/Inst/Conf-files/Unpacked/halF-conf/Half-inst/trig-aWait/Trig-pend');
    streams.stdout.writeLine('|/ Err?=(none)/Reinst-required (Status,Err: uppercase=bad)');
    streams.stdout.writeLine('||/ Name           Version      Architecture Description');
    streams.stdout.writeLine('+++-==============-============-============-=================================');

    const installed = getInstalledPackages();
    for (const name of installed) {
      const p = PACKAGE_DB.find(db => db.name === name);
      if (p) {
        streams.stdout.writeLine(`ii  \${p.name.padEnd(14, ' ')} \${p.version.padEnd(12, ' ')} amd64        \${p.description.split('\\n')[0]}`);
      }
    }
    return 0;
  }

  if (args.includes('--configure') && args.includes('-a')) {
    // Silent
    return 0;
  }

  streams.stderr.writeLine('dpkg: error: need an action option');
  return 2;
};

import type { CommandHandler } from './types';
import { parseArgs } from '../commandParser';

// Simulated archive format (JSON)
interface MockArchive {
  type: 'tar' | 'zip';
  files: {
    path: string;
    content: string;
    isDirectory: boolean;
  }[];
}

export const tar: CommandHandler = async (args, env, streams) => {
  const { flags, options, positional } = parseArgs(args, ['f']);

  if (!flags.c && !flags.x) {
    streams.stderr.writeLine('tar: must specify one of -c, -r, -t, -u, -x');
    return 1;
  }

  const isCreate = flags.c;
  const isExtract = flags.x;
  const isVerbose = flags.v;
  const archiveFile = options.f;

  if (!archiveFile) {
    streams.stderr.writeLine('tar: Refusing to read archive contents from terminal (missing -f option?)');
    return 1;
  }

  const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
  const { readFile, writeFile, stat, readdir, mkdir } = await import('../../../fs/operations');
  const cwdPath = await getAbsolutePathAsync(env.cwdId);

  if (isCreate) {
    const filesToArchive = positional;
    if (filesToArchive.length === 0) {
      streams.stderr.writeLine('tar: Cowardly refusing to create an empty archive');
      return 1;
    }

    const archiveData: MockArchive = { type: 'tar', files: [] };

    const addNodeToArchive = async (currentPath: string, archivePath: string) => {
      const node = await resolveRelativePathAsync(cwdPath, currentPath);
      if (!node) {
        streams.stderr.writeLine(`tar: ${currentPath}: Cannot stat: No such file or directory`);
        return;
      }

      const absPath = await getAbsolutePathAsync(node.id);
      const nodeStat = await stat(absPath);

      if (nodeStat.type === 'file') {
        const text = await (await readFile(absPath)).text();
        archiveData.files.push({ path: archivePath, content: text, isDirectory: false });
        if (isVerbose) streams.stdout.writeLine(archivePath);
      } else if (nodeStat.type === 'directory') {
        archiveData.files.push({ path: archivePath + '/', content: '', isDirectory: true });
        if (isVerbose) streams.stdout.writeLine(archivePath + '/');

        const children = await readdir(absPath);
        for (const child of children) {
          await addNodeToArchive(currentPath + '/' + child.name, archivePath + '/' + child.name);
        }
      }
    };

    for (const target of filesToArchive) {
      await addNodeToArchive(target, target);
    }

    // Save to VFS
    const parts = archiveFile.split('/');
    const destName = parts.pop()!;
    const parentPath = parts.join('/') || '.';
    const parentNode = await resolveRelativePathAsync(cwdPath, parentPath);
    if (!parentNode) {
      streams.stderr.writeLine(`tar: ${archiveFile}: Cannot open: No such file or directory`);
      return 1;
    }

    const parentAbs = await getAbsolutePathAsync(parentNode.id);
    const targetPath = parentAbs === '/' ? '/' + destName : parentAbs + '/' + destName;

    await writeFile(targetPath, JSON.stringify(archiveData));
    return 0;
  }

  if (isExtract) {
    const node = await resolveRelativePathAsync(cwdPath, archiveFile);
    if (!node) {
      streams.stderr.writeLine(`tar: ${archiveFile}: Cannot open: No such file or directory`);
      streams.stderr.writeLine('tar: Error is not recoverable: exiting now');
      return 2;
    }

    const absPath = await getAbsolutePathAsync(node.id);
    const blob = await readFile(absPath);
    const text = await blob.text();

    let archiveData: MockArchive;
    try {
      archiveData = JSON.parse(text);
      if (archiveData.type !== 'tar' && archiveData.type !== 'zip') throw new Error();
    } catch {
      streams.stderr.writeLine(`tar: This does not look like a tar archive`);
      streams.stderr.writeLine('tar: Error is not recoverable: exiting now');
      return 2;
    }

    for (const file of archiveData.files) {
      const fullExtractPath = cwdPath === '/' ? '/' + file.path : cwdPath + '/' + file.path;
      if (file.isDirectory) {
        try {
          await mkdir(fullExtractPath);
        } catch (e: any) {
          if (!e.message?.includes('exists')) {
            streams.stderr.writeLine(`tar: ${file.path}: Cannot mkdir: ${e.message}`);
          }
        }
        if (isVerbose) streams.stdout.writeLine(file.path);
      } else {
        // Ensure parent exists
        const parts = fullExtractPath.split('/');
        parts.pop();
        const dirPath = parts.join('/');
        try {
          if (dirPath !== '' && dirPath !== '/') {
             // Basic attempt to create missing parents sequentially
             const dirParts = dirPath.split('/').filter(Boolean);
             let curr = '';
             for (const dp of dirParts) {
               curr += '/' + dp;
               try { await mkdir(curr); } catch {}
             }
          }
          await writeFile(fullExtractPath, file.content);
          if (isVerbose) streams.stdout.writeLine(file.path);
        } catch (e: any) {
          streams.stderr.writeLine(`tar: ${file.path}: Cannot write: ${e.message}`);
        }
      }
    }
    return 0;
  }

  return 1;
};

export const zip: CommandHandler = async (args, env, streams) => {
  const { positional } = parseArgs(args);

  if (positional.length < 2) {
    streams.stderr.writeLine('zip error: Nothing to do!');
    return 1;
  }

  const archiveFile = positional[0];
  const filesToArchive = positional.slice(1);

  const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
  const { readFile, writeFile, stat, readdir } = await import('../../../fs/operations');
  const cwdPath = await getAbsolutePathAsync(env.cwdId);

  const archiveData: MockArchive = { type: 'zip', files: [] };

  const addNodeToArchive = async (currentPath: string, archivePath: string) => {
    const node = await resolveRelativePathAsync(cwdPath, currentPath);
    if (!node) {
      streams.stderr.writeLine(`zip warning: name not matched: ${currentPath}`);
      return;
    }

    const absPath = await getAbsolutePathAsync(node.id);
    const nodeStat = await stat(absPath);

    if (nodeStat.type === 'file') {
      const text = await (await readFile(absPath)).text();
      archiveData.files.push({ path: archivePath, content: text, isDirectory: false });
      streams.stdout.writeLine(`  adding: ${archivePath} (mock deflated 0%)`);
    } else if (nodeStat.type === 'directory') {
      archiveData.files.push({ path: archivePath + '/', content: '', isDirectory: true });
      streams.stdout.writeLine(`  adding: ${archivePath}/ (stored 0%)`);

      // zip normally doesn't recurse unless -r is given, but we will simplify and always recurse or assume user used -r.
      // Wait, let's only recurse if it was requested, or just do it for simplicity.
      // We will do it for simplicity since we don't fully parse -r here.
      const children = await readdir(absPath);
      for (const child of children) {
        await addNodeToArchive(currentPath + '/' + child.name, archivePath + '/' + child.name);
      }
    }
  };

  for (const target of filesToArchive) {
    await addNodeToArchive(target, target);
  }

  // Save to VFS
  const parts = archiveFile.split('/');
  const destName = parts.pop()!;
  const parentPath = parts.join('/') || '.';
  const parentNode = await resolveRelativePathAsync(cwdPath, parentPath);
  if (!parentNode) {
    streams.stderr.writeLine(`zip I/O error: No such file or directory`);
    return 1;
  }

  const parentAbs = await getAbsolutePathAsync(parentNode.id);
  const targetPath = parentAbs === '/' ? '/' + destName : parentAbs + '/' + destName;

  await writeFile(targetPath, JSON.stringify(archiveData));
  return 0;
};

export const unzip: CommandHandler = async (args, env, streams) => {
  const { positional } = parseArgs(args);

  if (positional.length === 0) {
    streams.stderr.writeLine('UnZip 6.00 of 20 April 2009, by Debian. Original by Info-ZIP.');
    return 1;
  }

  const archiveFile = positional[0];

  const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
  const { readFile, writeFile, mkdir } = await import('../../../fs/operations');
  const cwdPath = await getAbsolutePathAsync(env.cwdId);

  const node = await resolveRelativePathAsync(cwdPath, archiveFile);
  if (!node) {
    streams.stderr.writeLine(`unzip:  cannot find or open ${archiveFile}, ${archiveFile}.zip or ${archiveFile}.ZIP.`);
    return 9;
  }

  const absPath = await getAbsolutePathAsync(node.id);
  const blob = await readFile(absPath);
  const text = await blob.text();

  let archiveData: MockArchive;
  try {
    archiveData = JSON.parse(text);
    if (archiveData.type !== 'tar' && archiveData.type !== 'zip') throw new Error();
  } catch {
    streams.stderr.writeLine(`Archive:  ${archiveFile}`);
    streams.stderr.writeLine(`  End-of-central-directory signature not found.`);
    return 9;
  }

  streams.stdout.writeLine(`Archive:  ${archiveFile}`);

  for (const file of archiveData.files) {
    const fullExtractPath = cwdPath === '/' ? '/' + file.path : cwdPath + '/' + file.path;
    if (file.isDirectory) {
      try {
        await mkdir(fullExtractPath);
      } catch (e: any) {
        if (!e.message?.includes('exists')) {
          streams.stderr.writeLine(`   error:  cannot create ${file.path}`);
        }
      }
      streams.stdout.writeLine(`   creating: ${file.path}`);
    } else {
      // Ensure parent exists
      const parts = fullExtractPath.split('/');
      parts.pop();
      const dirPath = parts.join('/');
      try {
        if (dirPath !== '' && dirPath !== '/') {
           const dirParts = dirPath.split('/').filter(Boolean);
           let curr = '';
           for (const dp of dirParts) {
             curr += '/' + dp;
             try { await mkdir(curr); } catch {}
           }
        }
        await writeFile(fullExtractPath, file.content);
        streams.stdout.writeLine(`  inflating: ${file.path}`);
      } catch (e: any) {
        streams.stderr.writeLine(`error:  cannot create ${file.path}`);
      }
    }
  }

  return 0;
};

export const gzip: CommandHandler = async (args, env, streams) => {
  const { positional } = parseArgs(args);

  if (positional.length === 0) {
    streams.stderr.writeLine('gzip: compressed data not written to a terminal.');
    return 1;
  }

  const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
  const { readFile, writeFile, unlink } = await import('../../../fs/operations');
  const cwdPath = await getAbsolutePathAsync(env.cwdId);

  for (const target of positional) {
    const node = await resolveRelativePathAsync(cwdPath, target);
    if (!node) {
      streams.stderr.writeLine(`gzip: ${target}: No such file or directory`);
      continue;
    }

    if (node.type === 'directory') {
      streams.stderr.writeLine(`gzip: ${target} is a directory -- ignored`);
      continue;
    }

    const absPath = await getAbsolutePathAsync(node.id);
    const blob = await readFile(absPath);

    // Write new file .gz
    await writeFile(`${absPath}.gz`, await blob.text()); // Simulated compression, just rename/copy

    // Remove old file
    await unlink(absPath);
  }

  return 0;
};

export const gunzip: CommandHandler = async (args, env, streams) => {
  const { positional } = parseArgs(args);

  if (positional.length === 0) {
    streams.stderr.writeLine('gunzip: compressed data not read from a terminal.');
    return 1;
  }

  const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
  const { readFile, writeFile, unlink } = await import('../../../fs/operations');
  const cwdPath = await getAbsolutePathAsync(env.cwdId);

  for (const target of positional) {
    const node = await resolveRelativePathAsync(cwdPath, target);
    if (!node) {
      streams.stderr.writeLine(`gunzip: ${target}: No such file or directory`);
      continue;
    }

    if (node.type === 'directory') {
      streams.stderr.writeLine(`gunzip: ${target} is a directory -- ignored`);
      continue;
    }

    if (!target.endsWith('.gz')) {
      streams.stderr.writeLine(`gunzip: ${target}: unknown suffix -- ignored`);
      continue;
    }

    const absPath = await getAbsolutePathAsync(node.id);
    const blob = await readFile(absPath);

    // Write new file removing .gz
    const uncompressedPath = absPath.slice(0, -3);
    await writeFile(uncompressedPath, await blob.text()); 

    // Remove old file
    await unlink(absPath);
  }

  return 0;
};

import type { CommandHandler } from './types';
