export const envCmd: CommandHandler = (_args, env, streams) => {
  for (const [key, value] of Object.entries(env.envVars)) {
    streams.stdout.writeLine(`${key}=${value}`);
  }
  return 0;
};

export const exportCmd: CommandHandler = (args, env, streams) => {
  if (args.length === 0) {
    for (const [key, value] of Object.entries(env.envVars)) {
      streams.stdout.writeLine(`declare -x ${key}="${value}"`);
    }
    return 0;
  }

  for (const arg of args) {
    const eqIdx = arg.indexOf('=');
    if (eqIdx !== -1) {
      const key = arg.slice(0, eqIdx);
      const val = arg.slice(eqIdx + 1);
      env.updateEnv(key, val);
    }
  }

  return 0;
};

export const unsetCmd: CommandHandler = (args, env, _streams) => {
  for (const arg of args) {
    delete env.envVars[arg];
  }
  return 0;
};

export const whichCmd: CommandHandler = async (args, env, streams) => {
  if (args.length === 0) return 1;

  const { commandRegistry } = await import('./index');
  let exitCode = 0;

  for (const arg of args) {
    if (env.aliases[arg]) {
      streams.stdout.writeLine(`alias ${arg}='${env.aliases[arg]}'`);
    } else if (commandRegistry[arg]) {
      streams.stdout.writeLine(`/usr/bin/${arg}`);
    } else {
      exitCode = 1;
    }
  }

  return exitCode;
};

export const typeCmd: CommandHandler = async (args, env, streams) => {
  if (args.length === 0) return 1;

  const { commandRegistry } = await import('./index');
  let exitCode = 0;

  for (const arg of args) {
    if (env.aliases[arg]) {
      streams.stdout.writeLine(`${arg} is aliased to \`${env.aliases[arg]}'\``);
    } else if (['cd', 'pwd', 'history', 'help', 'exit', 'export', 'unset', 'alias', 'unalias', 'type'].includes(arg)) {
      streams.stdout.writeLine(`${arg} is a shell builtin`);
    } else if (commandRegistry[arg]) {
      streams.stdout.writeLine(`${arg} is /usr/bin/${arg}`);
    } else {
      streams.stderr.writeLine(`bash: type: ${arg}: not found`);
      exitCode = 1;
    }
  }

  return exitCode;
};

export const aliasCmd: CommandHandler = (args, env, streams) => {
  if (args.length === 0) {
    for (const [key, value] of Object.entries(env.aliases).sort()) {
      streams.stdout.writeLine(`alias ${key}='${value}'`);
    }
    return 0;
  }

  let exitCode = 0;
  for (const arg of args) {
    const eqIdx = arg.indexOf('=');
    if (eqIdx !== -1) {
      const key = arg.slice(0, eqIdx);
      const val = arg.slice(eqIdx + 1).replace(/^["']|["']$/g, '');
      env.setAlias(key, val);
    } else {
      if (env.aliases[arg]) {
        streams.stdout.writeLine(`alias ${arg}='${env.aliases[arg]}'`);
      } else {
        streams.stderr.writeLine(`bash: alias: ${arg}: not found`);
        exitCode = 1;
      }
    }
  }

  return exitCode;
};

export const unaliasCmd: CommandHandler = (args, env, streams) => {
  if (args.length === 0) {
    streams.stderr.writeLine(`unalias: usage: unalias [-a] name [name ...]`);
    return 1;
  }

  if (args[0] === '-a') {
    env.aliases = {};
    return 0;
  }

  let exitCode = 0;
  for (const arg of args) {
    if (env.aliases[arg]) {
      env.removeAlias(arg);
    } else {
      streams.stderr.writeLine(`bash: unalias: ${arg}: not found`);
      exitCode = 1;
    }
  }

  return exitCode;
};

export const sleepCmd: CommandHandler = async (args, env, streams) => {
  if (args.length === 0) {
    streams.stderr.writeLine(`sleep: missing operand`);
    return 1;
  }

  const seconds = parseFloat(args[0]);
  if (isNaN(seconds) || seconds < 0) {
    streams.stderr.writeLine(`sleep: invalid time interval '${args[0]}'`);
    return 1;
  }

  return new Promise<number>((resolve) => {
    let elapsed = 0;
    const intervalMs = 100;
    const totalMs = seconds * 1000;

    const interval = setInterval(() => {
      elapsed += intervalMs;
      if (env.abortSignal?.aborted) {
        clearInterval(interval);
        resolve(130); // 128 + 2 (SIGINT)
        return;
      }
      if (elapsed >= totalMs) {
        clearInterval(interval);
        resolve(0);
      }
    }, intervalMs);
  });
};

export const trueCmd: CommandHandler = () => 0;

export const falseCmd: CommandHandler = () => 1;

export const yesCmd: CommandHandler = async (args, env, streams) => {
  const str = args.length > 0 ? args.join(' ') : 'y';

  return new Promise<number>((resolve) => {
    let count = 0;
    const interval = setInterval(() => {
      if (env.abortSignal?.aborted) {
        clearInterval(interval);
        resolve(130);
        return;
      }

      for (let i = 0; i < 50; i++) {
        streams.stdout.writeLine(str);
      }
      count += 50;

      // Safety limit just in case
      if (count > 100000) {
        clearInterval(interval);
        resolve(0);
      }
    }, 50); // Yield to event loop
  });
};

export const seqCmd: CommandHandler = (args, _env, streams) => {
  if (args.length === 0) {
    streams.stderr.writeLine(`seq: missing operand`);
    return 1;
  }

  let start = 1;
  let increment = 1;
  let end = 1;

  if (args.length === 1) {
    end = parseFloat(args[0]);
  } else if (args.length === 2) {
    start = parseFloat(args[0]);
    end = parseFloat(args[1]);
  } else {
    start = parseFloat(args[0]);
    increment = parseFloat(args[1]);
    end = parseFloat(args[2]);
  }

  if (isNaN(start) || isNaN(increment) || isNaN(end)) {
    streams.stderr.writeLine(`seq: invalid floating point argument`);
    return 1;
  }

  if (increment === 0) return 1;

  let i = start;
  while ((increment > 0 && i <= end) || (increment < 0 && i >= end)) {
    // Avoid infinite loop if somehow floating point is weird
    if (Math.abs(i) > 1000000) break;
    streams.stdout.writeLine(i.toString());
    i += increment;
  }

  return 0;
};

export const printfCmd: CommandHandler = (args, _env, streams) => {
  if (args.length === 0) {
    streams.stderr.writeLine(`printf: usage: printf format [arguments]`);
    return 1;
  }

  const format = args[0]
    .replace(/\\n/g, '\n')
    .replace(/\\t/g, '\t');

  let argIdx = 1;
  let result = '';

  for (let i = 0; i < format.length; i++) {
    if (format[i] === '%' && i + 1 < format.length) {
      const type = format[i + 1];
      const val = args[argIdx] !== undefined ? args[argIdx] : '';

      if (type === 's') {
        result += val;
      } else if (type === 'd') {
        result += parseInt(val || '0', 10);
      } else if (type === 'f') {
        result += parseFloat(val || '0').toFixed(6);
      } else if (type === '%') {
        result += '%';
        argIdx--; // Did not consume arg
      } else {
        result += '%' + type;
        argIdx--;
      }
      i++;
      argIdx++;
    } else {
      result += format[i];
    }
  }

  // Write line handles newline, but printf shouldn't add a trailing newline automatically unless \n is provided.
  // Wait, streams.stdout.writeLine adds \n.
  // We can write it via writeLine but strip the last \n if present, or just let writeLine handle it.
  // A true terminal stream has `write` vs `writeLine`. We only have `writeLine` which adds `\r\n`.
  // To avoid adding extra newlines, we should split by \n and writeLine.
  const parts = result.split('\n');
  for (let i = 0; i < parts.length; i++) {
    if (i === parts.length - 1 && parts[i] === '') break;
    streams.stdout.writeLine(parts[i]);
  }

  return 0;
};

export const man: CommandHandler = (args, _env, streams) => {
  if (args.length === 0) {
    streams.stderr.writeLine('What manual page do you want?');
    return 1;
  }

  const cmd = args[0];
  const pages: Record<string, string[]> = {
    ls: [
      'LS(1)                            User Commands                           LS(1)',
      '',
      'NAME',
      '       ls - list directory contents',
      '',
      'SYNOPSIS',
      '       ls [OPTION]... [FILE]...',
      '',
      'DESCRIPTION',
      '       List information about the FILEs (the current directory by default).',
      '       Sort entries alphabetically if none of -cftuvSUX nor --sort is speci‐',
      '       fied.'
    ],
    cat: [
      'CAT(1)                           User Commands                          CAT(1)',
      '',
      'NAME',
      '       cat - concatenate files and print on the standard output',
      '',
      'SYNOPSIS',
      '       cat [OPTION]... [FILE]...',
      '',
      'DESCRIPTION',
      '       Concatenate FILE(s) to standard output.'
    ]
  };

  if (pages[cmd]) {
    pages[cmd].forEach(l => streams.stdout.writeLine(l));
    return 0;
  }

  streams.stderr.writeLine(`No manual entry for ${cmd}`);
  return 1;
};

export const cal: CommandHandler = (_args, _env, streams) => {
  const now = new Date();
  const year = now.getFullYear();
  const month = now.getMonth();

  const monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

  const firstDay = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();

  const today = now.getDate();

  const header = `    ${monthNames[month]} ${year}`;
  streams.stdout.writeLine(header);
  streams.stdout.writeLine('Su Mo Tu We Th Fr Sa');

  let line = '';
  for (let i = 0; i < firstDay; i++) {
    line += '   ';
  }

  for (let d = 1; d <= daysInMonth; d++) {
    const dStr = d.toString().padStart(2, ' ');
    if (d === today) {
      // Highlight today (invert)
      line += `\x1b[7m${dStr}\x1b[0m `;
    } else {
      line += `${dStr} `;
    }

    if ((firstDay + d) % 7 === 0) {
      streams.stdout.writeLine(line.slice(0, -1));
      line = '';
    }
  }

  if (line.length > 0) {
    streams.stdout.writeLine(line.trimEnd());
  }

  return 0;
};

export const bc: CommandHandler = (args, _env, streams) => {
  // We'll evaluate an expression passed via stdin or args, or start a simple interactive REPL
  // (Interactive REPL is hard in this mock environment, so we'll just handle stdin)
  const input = streams.stdin.readAll().trim() || args.join(' ');

  if (!input) {
    streams.stdout.writeLine('bc 1.07.1');
    streams.stdout.writeLine('Copyright 1991-1994, 1997, 1998, 2000, 2004, 2006, 2008, 2012-2017 Free Software Foundation, Inc.');
    // Real bc would wait for stdin lines here. We just exit.
    return 0;
  }

  try {
    // A very rudimentary and unsafe eval-based parser. We'll strip anything not math related.
    const safeInput = input.replace(/[^0-9+\-*/%(). ]/g, '');
    if (safeInput !== input) {
      throw new Error('Invalid syntax');
    }
    const result = new Function(`return ${safeInput}`)();
    streams.stdout.writeLine(result.toString());
  } catch {
    streams.stderr.writeLine('Runtime error (func=(main), adr=3): syntax error');
    return 1;
  }

  return 0;
};

export const diff: CommandHandler = async (args, env, streams) => {
  if (args.length < 2) {
    streams.stderr.writeLine('diff: missing operand after');
    return 1;
  }

  const file1 = args[0];
  const file2 = args[1];

  try {
    const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
    const { readFile } = await import('../../../fs/operations');
    const cwdPath = await getAbsolutePathAsync(env.cwdId);

    const node1 = await resolveRelativePathAsync(cwdPath, file1);
    const node2 = await resolveRelativePathAsync(cwdPath, file2);

    if (!node1) { streams.stderr.writeLine(`diff: ${file1}: No such file or directory`); return 1; }
    if (!node2) { streams.stderr.writeLine(`diff: ${file2}: No such file or directory`); return 1; }

    const absPath1 = await getAbsolutePathAsync(node1.id);
    const absPath2 = await getAbsolutePathAsync(node2.id);

    const text1 = await (await readFile(absPath1)).text();
    const text2 = await (await readFile(absPath2)).text();

    const lines1 = text1.split('\n');
    const lines2 = text2.split('\n');

    // Very naive diff
    let hasDiff = false;
    for (let i = 0; i < Math.max(lines1.length, lines2.length); i++) {
      if (lines1[i] !== lines2[i]) {
        hasDiff = true;
        if (lines1[i] !== undefined) streams.stdout.writeLine(`\x1b[31m- ${lines1[i]}\x1b[0m`);
        if (lines2[i] !== undefined) streams.stdout.writeLine(`\x1b[32m+ ${lines2[i]}\x1b[0m`);
      } else {
        streams.stdout.writeLine(`  ${lines1[i]}`);
      }
    }

    return hasDiff ? 1 : 0;
  } catch (e: any) {
    streams.stderr.writeLine(`diff: ${e.message}`);
    return 2;
  }
};

export const md5sum: CommandHandler = async (args, env, streams) => {
  return hashsum(args, env, streams, 'MD5');
};

export const sha256sum: CommandHandler = async (args, env, streams) => {
  return hashsum(args, env, streams, 'SHA-256');
};

const hashsum = async (args: string[], env: any, streams: any, algo: string) => {
  if (args.length === 0) {
    streams.stderr.writeLine(`${algo.toLowerCase()}sum: missing operand`);
    return 1;
  }

  let exitCode = 0;

  for (const target of args) {
    try {
      const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
      const { readFile } = await import('../../../fs/operations');
      const cwdPath = await getAbsolutePathAsync(env.cwdId);

      const node = await resolveRelativePathAsync(cwdPath, target);
      if (!node) {
        streams.stderr.writeLine(`${algo.toLowerCase()}sum: ${target}: No such file or directory`);
        exitCode = 1;
        continue;
      }

      if (node.type === 'directory') {
        streams.stderr.writeLine(`${algo.toLowerCase()}sum: ${target}: Is a directory`);
        exitCode = 1;
        continue;
      }

      const absPath = await getAbsolutePathAsync(node.id);
      const blob = await readFile(absPath);
      const buffer = await blob.arrayBuffer();

      let digest: ArrayBuffer;
      if (algo === 'MD5') {
        // Web crypto doesn't support MD5, we'll fake it deterministically based on length and first bytes
        const fakeHash = Array.from(new Uint8Array(buffer).slice(0, 16)).map(b => b.toString(16).padStart(2, '0')).join('');
        digest = new TextEncoder().encode(fakeHash.padEnd(32, '0').slice(0, 32)).buffer;
      } else {
        digest = await crypto.subtle.digest(algo, buffer);
      }

      const hashArray = Array.from(new Uint8Array(digest));
      const hashHex = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');

      streams.stdout.writeLine(`${hashHex}  ${target}`);
    } catch (e: any) {
      streams.stderr.writeLine(`${algo.toLowerCase()}sum: ${target}: ${e.message}`);
      exitCode = 1;
    }
  }

  return exitCode;
};

export const xxd: CommandHandler = async (args, env, streams) => {
  if (args.length === 0) {
    streams.stderr.writeLine('xxd: missing operand');
    return 1;
  }

  try {
    const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
    const { readFile } = await import('../../../fs/operations');
    const cwdPath = await getAbsolutePathAsync(env.cwdId);

    const node = await resolveRelativePathAsync(cwdPath, args[0]);
    if (!node) {
      streams.stderr.writeLine(`xxd: ${args[0]}: No such file or directory`);
      return 1;
    }

    if (node.type === 'directory') {
      streams.stderr.writeLine(`xxd: ${args[0]}: Is a directory`);
      return 1;
    }

    const absPath = await getAbsolutePathAsync(node.id);
    const blob = await readFile(absPath);
    const arrayBuffer = await blob.arrayBuffer();
    const bytes = new Uint8Array(arrayBuffer);

    for (let i = 0; i < bytes.length; i += 16) {
      const offset = i.toString(16).padStart(8, '0');
      let hexPart = '';
      let asciiPart = '';

      for (let j = 0; j < 16; j++) {
        if (i + j < bytes.length) {
          const b = bytes[i + j];
          hexPart += b.toString(16).padStart(2, '0');
          if (j % 2 !== 0) hexPart += ' ';

          if (b >= 32 && b <= 126) asciiPart += String.fromCharCode(b);
          else asciiPart += '.';
        } else {
          hexPart += '  ';
          if (j % 2 !== 0) hexPart += ' ';
        }
      }

      streams.stdout.writeLine(`${offset}: ${hexPart} ${asciiPart}`);
    }

    return 0;
  } catch (e: any) {
    streams.stderr.writeLine(`xxd: ${e.message}`);
    return 1;
  }
};

// import removed: useVFSStore

/**
 * Result of attempting to open nano/vi on a file.
 * If successful, returns the fileId to pass to NanoEditor.
 * If failed, returns an error CommandResult for display.
 */
export interface NanoOpenResult {
  fileId?: string;
  error?: {
    output: string[];
    isError: boolean;
  };
}

/**
 * Handle the nano/vi command: validate args, resolve or create the file,
 * and return the fileId for the NanoEditor to open.
 *
 * This is a special-case handler — NOT registered in commandRegistry
 * because it triggers an interactive mode, not a simple CommandResult.
 *
 * @param commandName - 'nano' or 'vi' (for error messages)
 * @param args - Command arguments (expected: exactly one filename)
 * @param env.cwdId - Current working directory ID
 */
export async function handleNano(commandName: string, args: string[], cwdId: string): Promise<NanoOpenResult> {
  if (args.length === 0) {
    return {
      error: { output: [`${commandName}: missing filename`], isError: true },
    };
  }

  const targetName = args[0];
  const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
  const { writeFile } = await import('../../../fs/operations');

  const cwdPath = await getAbsolutePathAsync(cwdId);
  let node = await resolveRelativePathAsync(cwdPath, targetName);

  if (!node) {
    let destName = targetName;
    let destParentPath = '.';
    if (targetName.includes('/')) {
      const parts = targetName.split('/');
      destName = parts.pop()!;
      destParentPath = parts.join('/') || (targetName.startsWith('/') ? '/' : '.');
    }

    const parentNode = await resolveRelativePathAsync(cwdPath, destParentPath);
    if (!parentNode) {
      return { error: { output: [`${commandName}: cannot create '${targetName}': No such file or directory`], isError: true } };
    }
    if (parentNode.type !== 'directory') {
      return { error: { output: [`${commandName}: cannot create '${targetName}': Not a directory`], isError: true } };
    }

    const parentAbsPath = await getAbsolutePathAsync(parentNode.id);
    const newFilePath = parentAbsPath === '/' ? '/' + destName : parentAbsPath + '/' + destName;

    try {
      await writeFile(newFilePath, new Blob([]));
      node = await resolveRelativePathAsync(cwdPath, targetName);
    } catch (err: any) {
      return {
        error: { output: [`${commandName}: ${err.message}`], isError: true },
      };
    }
  }

  if (!node) {
    return {
      error: { output: [`${commandName}: failed to create file`], isError: true },
    };
  }

  if (node.type === 'directory') {
    return {
      error: { output: [`${commandName}: ${targetName} is a directory`], isError: true },
    };
  }

  return { fileId: node.id };
}

import type { CommandHandler } from './types';
import { getAuthContext } from '../../../store/useUbuntuVFSStore';
import { getHomeId } from '../../../fs/seed';
import { hasPermission } from '../../../fs/permissions';

export const pwd: CommandHandler = async (_args, env, streams) => {
  const { getAbsolutePathAsync } = await import('../../../fs/pathResolver');
  const path = await getAbsolutePathAsync(env.cwdId);
  [path].forEach((line: string) => streams.stdout.writeLine(line)); return 0;
};

export const cd: CommandHandler = async (args, env, streams) => {
  const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
  const username = env.effectiveUser || getAuthContext().username;
  const HOME_ID = getHomeId(username);

  if (args.length === 0) {
    env.cwdId = HOME_ID;
    env.cwdPath = await getAbsolutePathAsync(HOME_ID);
    return 0;
  }

  let path = args[0];

  if (path === '~') {
    env.cwdId = HOME_ID;
    env.cwdPath = await getAbsolutePathAsync(HOME_ID);
    return 0;
  }

  if (path.startsWith('~/')) {
    const homePath = await getAbsolutePathAsync(HOME_ID);
    path = path.replace('~', homePath);
  }

  const cwdPath = await getAbsolutePathAsync(env.cwdId);
  const node = await resolveRelativePathAsync(cwdPath, path);

  if (!node) {
    [`cd: ${args[0]}: No such file or directory`].forEach((line: string) => streams.stderr.writeLine(line)); return 1;
  }

  if (node.type !== 'directory') {
    [`cd: ${args[0]}: Not a directory`].forEach((line: string) => streams.stderr.writeLine(line)); return 1;
  }

  if (!hasPermission(node, 'execute', username)) {
    [`cd: ${args[0]}: Permission denied`].forEach((line: string) => streams.stderr.writeLine(line)); return 1;
  }

  env.cwdId = node.id;
  env.cwdPath = await getAbsolutePathAsync(node.id);
  return 0;
};

export const ls: CommandHandler = async (args, env, streams) => {
  const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
  const { readdir } = await import('../../../fs/operations');

  let showHidden = false;
  let longFormat = false;
  let targetPath = '.';

  for (const arg of args) {
    if (arg.startsWith('-')) {
      if (arg.includes('a')) showHidden = true;
      if (arg.includes('l')) longFormat = true;
    } else {
      targetPath = arg;
    }
  }

  const cwdPath = await getAbsolutePathAsync(env.cwdId);
  const targetNode = await resolveRelativePathAsync(cwdPath, targetPath);

  if (!targetNode) {
    streams.stderr.writeLine(`ls: cannot access '${targetPath}': No such file or directory`); 
    return 1;
  }

  let children: any[] = [];
  if (targetNode.type === 'directory') {
    const targetAbsPath = await getAbsolutePathAsync(targetNode.id);
    children = await readdir(targetAbsPath);
  } else {
    children = [targetNode];
  }

  if (!showHidden && targetNode.type === 'directory') {
    children = children.filter(c => !c.name.startsWith('.'));
  }

  if (longFormat) {
    const outputLines = children.map(c => {
      const typeChar = c.type === 'directory' ? 'd' : '-';
      let perms = c.permissions ? c.permissions.toString(8) : (c.type === 'directory' ? '755' : '644');
      if (perms.length < 3) perms = perms.padStart(3, '0');

      const rwx = perms.split('').slice(-3).map((digit: string) => {
        const val = parseInt(digit, 8);
        return (val & 4 ? 'r' : '-') + (val & 2 ? 'w' : '-') + (val & 1 ? 'x' : '-');
      }).join('');

      const permString = `${typeChar}${rwx}`;
      const links = 1;
      const owner = c.ownerId || 'user';
      const group = c.groupId || 'user';
      const size = c.sizeBytes || 0;

      const dateObj = new Date(c.modifiedAt);
      const dateStr = dateObj.toLocaleDateString('en-US', { month: 'short', day: '2-digit' }) + ' ' + 
                      dateObj.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: false });

      const isExecutable = c.type !== 'directory' && (c.permissions ? (c.permissions & 1) || (c.permissions & 8) || (c.permissions & 64) : false);
      let nameStr = c.name;
      if (c.type === 'directory') nameStr = `\x1b[1;34m${c.name}\x1b[0m`;
      else if (c.type === 'symlink') nameStr = `\x1b[1;36m${c.name}\x1b[0m`;
      else if (isExecutable) nameStr = `\x1b[1;32m${c.name}\x1b[0m`;

      return `${permString} ${links} ${owner} ${group} ${size.toString().padStart(5, ' ')} ${dateStr} ${nameStr}`;
    });

    outputLines.forEach((line: string) => streams.stdout.writeLine(line)); return 0;
  }

  const items = children.map(c => {
    const isExecutable = c.type !== 'directory' && (c.permissions ? (c.permissions & 1) || (c.permissions & 8) || (c.permissions & 64) : false);
    if (c.type === 'directory') return `\x1b[1;34m${c.name}/\x1b[0m`;
    if (c.type === 'symlink') return `\x1b[1;36m${c.name}\x1b[0m`;
    if (isExecutable) return `\x1b[1;32m${c.name}\x1b[0m`;
    return c.name;
  });

  if (items.length > 0) {
    const stripAnsi = (str: string) => str.replace(/\x1b\[[0-9;]*m/g, '');
    items.sort((a, b) => stripAnsi(a).toLowerCase().localeCompare(stripAnsi(b).toLowerCase()));

    const terminalWidth = 100;
    const maxLen = Math.max(...items.map(s => stripAnsi(s).length));
    const colWidth = maxLen + 2; 
    const cols = Math.max(1, Math.floor(terminalWidth / colWidth));
    const rows = Math.ceil(items.length / cols);

    for (let r = 0; r < rows; r++) {
      let line = '';
      for (let c = 0; c < cols; c++) {
        const index = c * rows + r;
        if (index < items.length) {
          const item = items[index];
          const visibleLen = stripAnsi(item).length;
          line += item + ' '.repeat(colWidth - visibleLen);
        }
      }
      streams.stdout.writeLine(line.trimEnd());
    }
  }

  return 0;
};

import type { CommandHandler } from './types';
import { parseArgs } from '../commandParser';

export const ping: CommandHandler = async (args, env, streams) => {
  const { options, positional } = parseArgs(args, ['c']);

  if (positional.length === 0) {
    streams.stderr.writeLine('ping: usage error: Destination address required');
    return 1;
  }

  const host = positional[0];
  const count = parseInt(options.c || '4', 10);

  if (isNaN(count) || count <= 0) {
    streams.stderr.writeLine(`ping: bad number of packets to transmit.`);
    return 1;
  }

  // Fake IP for host
  const ip = `142.250.${Math.floor(Math.random() * 255)}.${Math.floor(Math.random() * 255)}`;

  streams.stdout.writeLine(`PING ${host} (${ip}) 56(84) bytes of data.`);

  let packetsSent = 0;
  let packetsReceived = 0;
  let minTime = Infinity;
  let maxTime = -Infinity;
  let sumTime = 0;
  const startTime = Date.now();

  for (let i = 1; i <= count; i++) {
    // Simulate delay
    await new Promise(r => setTimeout(r, 1000));

    if (env.abortSignal?.aborted) {
      break;
    }

    const latency = 10 + Math.random() * 70; // 10-80ms
    const timeStr = latency.toFixed(1);

    streams.stdout.writeLine(`64 bytes from ${ip}: icmp_seq=${i} ttl=117 time=${timeStr} ms`);
    packetsSent++;
    packetsReceived++;
    minTime = Math.min(minTime, latency);
    maxTime = Math.max(maxTime, latency);
    sumTime += latency;
  }

  const totalTime = Date.now() - startTime;

  streams.stdout.writeLine(`--- ${host} ping statistics ---`);
  streams.stdout.writeLine(`${packetsSent} packets transmitted, ${packetsReceived} received, 0% packet loss, time ${totalTime}ms`);

  if (packetsReceived > 0) {
    const avg = sumTime / packetsReceived;
    const mdev = Math.random() * 2;
    streams.stdout.writeLine(`rtt min/avg/max/mdev = ${minTime.toFixed(3)}/${avg.toFixed(3)}/${maxTime.toFixed(3)}/${mdev.toFixed(3)} ms`);
  }

  return 0;
};

export const curl: CommandHandler = async (args, env, streams) => {
  const { flags, options, positional } = parseArgs(args, ['o']);

  if (positional.length === 0) {
    streams.stderr.writeLine('curl: try \'curl --help\' for more information');
    return 1;
  }

  const url = positional[0];
  const isSilent = flags.s;
  const isHead = flags.I;
  const outputFile = options.o;

  let content = '';
  let contentType = 'text/html';
  let status = '200 OK';

  if (url.startsWith('file://')) {
    try {
      const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
      const { readFile } = await import('../../../fs/operations');
      const cwdPath = await getAbsolutePathAsync(env.cwdId);

      const targetPathStr = url.replace('file://', '');
      const node = await resolveRelativePathAsync(cwdPath, targetPathStr);
      if (!node) throw new Error();

      const absPath = await getAbsolutePathAsync(node.id);
      const blob = await readFile(absPath);
      content = await blob.text();
      contentType = 'text/plain'; // Approximation
    } catch {
      if (!isSilent) streams.stderr.writeLine(`curl: (37) Couldn't open file ${url}`);
      return 37;
    }
  } else {
    // Mock web fetch
    try {
      if (url.includes('google.com')) {
        content = '<!doctype html><html itemscope="" itemtype="http://schema.org/WebPage" lang="en"><head><meta content="text/html; charset=UTF-8" http-equiv="Content-Type"><title>Google</title></head><body>...</body></html>';
      } else {
        content = `<html><head><title>Mock Response for ${url}</title></head><body><h1>Welcome to ${url}</h1><p>This is a simulated response.</p></body></html>`;
      }
    } catch (e: any) {
      if (!isSilent) streams.stderr.writeLine(`curl: (6) Could not resolve host: ${url}`);
      return 6;
    }
  }

  if (isHead) {
    const headers = [
      `HTTP/1.1 ${status}`,
      `Content-Type: ${contentType}`,
      `Content-Length: ${content.length}`,
      `Date: ${new Date().toUTCString()}`,
      `Server: mock-server`,
      ``
    ];
    headers.forEach(h => streams.stdout.writeLine(h));
    return 0;
  }

  if (outputFile) {
    try {
      const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
      const { writeFile } = await import('../../../fs/operations');
      const cwdPath = await getAbsolutePathAsync(env.cwdId);

      let targetPath = '';
      const node = await resolveRelativePathAsync(cwdPath, outputFile);
      if (node) {
        targetPath = await getAbsolutePathAsync(node.id);
      } else {
        const parts = outputFile.split('/');
        const destName = parts.pop()!;
        const parentPath = parts.join('/') || '.';
        const parentNode = await resolveRelativePathAsync(cwdPath, parentPath);
        if (!parentNode) throw new Error();
        const parentAbs = await getAbsolutePathAsync(parentNode.id);
        targetPath = parentAbs === '/' ? '/' + destName : parentAbs + '/' + destName;
      }

      await writeFile(targetPath, content);

      if (!isSilent) {
        streams.stderr.writeLine(`  % Total    % Received % Xferd  Average Speed   Time    Time     Time  Current`);
        streams.stderr.writeLine(`                                 Dload  Upload   Total   Spent    Left  Speed`);
        streams.stderr.writeLine(`100  ${content.length}  100  ${content.length}    0     0   ${content.length}      0 --:--:-- --:--:-- --:--:--  ${content.length}`);
      }
    } catch {
      if (!isSilent) streams.stderr.writeLine(`curl: (23) Failed writing body`);
      return 23;
    }
  } else {
    streams.stdout.writeLine(content);
  }

  return 0;
};

export const wget: CommandHandler = async (args, env, streams) => {
  const { flags, options, positional } = parseArgs(args, ['O']);

  if (positional.length === 0) {
    streams.stderr.writeLine('wget: missing URL');
    streams.stderr.writeLine('Usage: wget [OPTION]... [URL]...');
    return 1;
  }

  const url = positional[0];
  const isSilent = flags.q;

  let outputFile = options.O;
  if (!outputFile) {
    try {
      const parsedUrl = new URL(url);
      const parts = parsedUrl.pathname.split('/');
      outputFile = parts[parts.length - 1] || 'index.html';
    } catch {
      outputFile = 'index.html';
    }
  }

  if (!isSilent) {
    const date = new Date().toISOString().replace('T', ' ').slice(0, 19);
    streams.stderr.writeLine(`--${date}--  ${url}`);

    // Fake IP resolution
    const domain = url.replace(/https?:\/\//, '').split('/')[0] || 'example.com';
    const fakeIp = `93.184.${Math.floor(Math.random() * 255)}.${Math.floor(Math.random() * 255)}`;

    streams.stderr.writeLine(`Resolving ${domain}... ${fakeIp}`);
    streams.stderr.writeLine(`Connecting to ${domain}|${fakeIp}|:443... connected.`);
    streams.stderr.writeLine(`HTTP request sent, awaiting response... 200 OK`);
  }

  const content = `Mock downloaded content from ${url}`;

  try {
    const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
    const { writeFile } = await import('../../../fs/operations');
    const cwdPath = await getAbsolutePathAsync(env.cwdId);

    let targetPath = '';
    const node = await resolveRelativePathAsync(cwdPath, outputFile);
    if (node) {
      targetPath = await getAbsolutePathAsync(node.id);
    } else {
      const parts = outputFile.split('/');
      const destName = parts.pop()!;
      const parentPath = parts.join('/') || '.';
      const parentNode = await resolveRelativePathAsync(cwdPath, parentPath);
      if (!parentNode) throw new Error();
      const parentAbs = await getAbsolutePathAsync(parentNode.id);
      targetPath = parentAbs === '/' ? '/' + destName : parentAbs + '/' + destName;
    }

    await writeFile(targetPath, content);

    if (!isSilent) {
      streams.stderr.writeLine(`Length: ${content.length} [text/plain]`);
      streams.stderr.writeLine(`Saving to: '${outputFile}'`);
      streams.stderr.writeLine(`${outputFile.padEnd(16)} 100%[===================>] ${content.length}  --.-KB/s    in 0s`);
    }

    return 0;
  } catch (e) {
    streams.stderr.writeLine(`${outputFile}: Permission denied`);
    return 1;
  }
};

