export const nohup: CommandHandler = async (args, env, streams) => {
  if (args.length === 0) {
    streams.stderr.writeLine('nohup: missing operand');
    streams.stderr.writeLine(`Try 'nohup --help' for more information.`);
    return 1;
  }

  streams.stderr.writeLine(`nohup: ignoring input and appending output to 'nohup.out'`);

  // Since we don't have a real background job runner, we just run the command synchronously.
  // We should ideally run it and pipe its stdout to nohup.out
  const { commandRegistry } = await import('./index');
  const cmdName = args[0];
  const cmdArgs = args.slice(1);

  const handler = commandRegistry[cmdName];
  if (!handler) {
    streams.stderr.writeLine(`nohup: failed to run command '${cmdName}': No such file or directory`);
    return 127;
  }

  // Mock standard streams for nohup to pipe output to nohup.out
  let outContent = '';
  const dummyStream = {
    write: (data: string) => outContent += data,
    writeLine: (data: string) => outContent += data + '\n',
    readAll: () => '',
    readLines: () => [],
    appendToBuffer: () => {},
    onData: () => () => {},
    clearListeners: () => {}
  } as any;

  const mockStreams = {
    stdin: streams.stdin,
    stdout: dummyStream,
    stderr: dummyStream
  };

  let exitCode = 0;
  try {
    if (typeof handler === 'function') {
       exitCode = await handler(cmdArgs, env, mockStreams) ?? 0;
    } else if (typeof handler === 'object' && 'run' in handler) {
       exitCode = await (handler as any).run(cmdArgs, env, mockStreams) ?? 0;
    }
  } catch (err: any) {
    outContent += err.message + '\n';
    exitCode = 1;
  }

  try {
    const { getAbsolutePathAsync } = await import('../../../fs/pathResolver');
    const { writeFile } = await import('../../../fs/operations');
    const cwdPath = await getAbsolutePathAsync(env.cwdId);
    await writeFile(`${cwdPath === '/' ? '' : cwdPath}/nohup.out`, outContent, { append: true });
  } catch {}

  return exitCode;
};

export const xargs: CommandHandler = async (args, env, streams) => {
  const { options, positional } = parseArgs(args, ['n']);

  if (positional.length === 0) {
    positional.push('echo');
  }

  const cmdName = positional[0];
  const initialArgs = positional.slice(1);
  const n = parseInt(options.n || '0', 10);

  const stdinContent = streams.stdin.readAll().trim();
  if (!stdinContent) return 0;

  const tokens = stdinContent.split(/\s+/).filter(Boolean);
  const { commandRegistry } = await import('./index');
  const handler = commandRegistry[cmdName];

  if (!handler) {
    streams.stderr.writeLine(`xargs: ${cmdName}: No such file or directory`);
    return 127;
  }

  let exitCode = 0;

  const batchSize = n > 0 ? n : tokens.length;

  for (let i = 0; i < tokens.length; i += batchSize) {
    const batch = tokens.slice(i, i + batchSize);
    const cmdArgs = [...initialArgs, ...batch];

    try {
      if (typeof handler === 'function') {
         exitCode = await handler(cmdArgs, env, streams) ?? 0;
      } else if (typeof handler === 'object' && 'run' in handler) {
         exitCode = await (handler as any).run(cmdArgs, env, streams) ?? 0;
      }
    } catch (err: any) {
      streams.stderr.writeLine(err.message);
      exitCode = 1;
    }

    if (exitCode !== 0) break;
  }

  return exitCode;
};

import type { CommandHandler } from './types';
import { parseArgs } from '../commandParser';

/**
 * history — Display or clear the command history.
 *
 * Usage:
 *   history       Show all past commands with line numbers
 *   history -c    Clear the command history
 *
 * Reads from env.commandHistory (5th parameter).
 */
export const history: CommandHandler = (args, env, streams) => {
  const { flags } = parseArgs(args);

  if (flags.c) {
    [].forEach((line: string) => streams.stdout.writeLine(line)); return 0;
  }

  if (!env?.commandHistory || env.commandHistory.length === 0) {
    [].forEach((line: string) => streams.stdout.writeLine(line)); return 0;
  }

  const lines = env.commandHistory.map((cmd, index) => {
    const num = (index + 1).toString().padStart(5, ' ');
    return `${num}  ${cmd}`;
  });

  lines.forEach((line: string) => streams.stdout.writeLine(line)); return 0;
};

export const bash: CommandHandler = async (args, env, streams) => {
  if (args.length === 0) {
    streams.stderr.writeLine('bash: no script file specified');
    return 1;
  }

  const scriptPath = args[0];
  const scriptArgs = args.slice(1);

  try {
    const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
    const { readFile } = await import('../../../fs/operations');

    const cwdAbs = await getAbsolutePathAsync(env.cwdId);
    const node = await resolveRelativePathAsync(cwdAbs, scriptPath);
    if (!node) {
      streams.stderr.writeLine(`bash: ${scriptPath}: No such file or directory`);
      return 127;
    }

    const absPath = await getAbsolutePathAsync(node.id);
    const blob = await readFile(absPath);
    const content = await blob.text();

    // Create new env for child script (inherit vars, but not aliases unless configured, for now just copy)
    // Wait, let's just use the same env but backup/restore positionalArgs
    const oldArgs = [...env.positionalArgs];
    env.positionalArgs = [scriptPath, ...scriptArgs];

    const { ScriptParser } = await import('../engine/ScriptParser');
    const { ScriptRunner } = await import('../engine/ScriptRunner');

    const parser = new ScriptParser(content);
    const ast = parser.parse();

    const runner = new ScriptRunner(env, streams);
    const exitCode = await runner.execute(ast);

    env.positionalArgs = oldArgs;
    return exitCode;
  } catch (e: any) {
    streams.stderr.writeLine(`bash: ${e.message}`);
    return 1;
  }
};

