export const read: CommandHandler = async (args, env, streams) => {
  const { flags, options, positional } = parseArgs(args, ['p', 'n']);
  const prompt = options.p || '';
  const isSilent = flags.s;
  // Options -n is not fully supported in this interactiveRead mock yet

  if (env.interactiveRead) {
    const input = await env.interactiveRead(prompt, isSilent);
    if (env.abortSignal?.aborted) return 130;

    if (positional.length > 0) {
      env.updateEnv(positional[0], input);
    } else {
      env.updateEnv('REPLY', input);
    }
    return 0;
  } else {
    // Fallback if not interactive
    const input = streams.stdin.readAll().trim();
    if (positional.length > 0) {
      env.updateEnv(positional[0], input);
    } else {
      env.updateEnv('REPLY', input);
    }
    return 0;
  }
};

import type { CommandHandler } from './types';
// import removed: useUbuntuVFSStore

/**
 * su — Switch user.
 *
 * Usage:
 *   su [username]      Switch to username (default: root)
 *   su - [username]    Switch and load the user's environment
 *   exit               Return to the previous user (handled in Terminal.tsx)
 *
 * Unlike sudo, `su` requires the TARGET user's password (not the current user's).
 *
 * This command sets a flag in the terminal app state that tells Terminal.tsx
 * to enter password-prompt mode for the target user, and upon success,
 * pushes the current user onto the userStack and sets effectiveUser.
 */
export const su: CommandHandler = async (args, env, streams) => {
  let targetUser = 'root';

  for (const arg of args) {
    if (arg === '-' || arg === '-l' || arg === '--login') {
      // loginShell = true; // Unused
    } else if (!arg.startsWith('-')) {
      targetUser = arg;
    }
  }

  let userExists = targetUser === 'root';
  try {
    const { readFile } = await import('../../../fs/operations');
    const blob = await readFile('/etc/passwd');
    const text = await blob.text();
    const lines = text.split('\n');
    if (lines.some(l => l.startsWith(targetUser + ':'))) {
      userExists = true;
    }
  } catch(e) {}

  const currentUser = env.effectiveUser;

  if (!userExists) {
    streams.stderr.writeLine(`su: user ${targetUser} does not exist`);
    return 1;
  } else if (targetUser === currentUser) {
    streams.stderr.writeLine(`su: user ${targetUser} is already logged in`);
    return 1;
  }

  // In a real terminal, we would prompt for a password via stdin.
  // For now, we simulate success for the refactor.
  env.pushUser(targetUser);
  return 0;
};

import type { CommandHandler } from './types';
import { commandRegistry } from './index';
import { parseArgs } from '../commandParser';
import {
  checkSudoAuthorization,
  isSudoCached,
  withElevation,
} from '../../../services/sudoService';
import { useUbuntuAuthStore } from '../../../store/useUbuntuAuthStore';

export const sudo: CommandHandler = async (args, env, streams) => {
  const { flags, options, positional } = parseArgs(args, ['u']);
  const targetUser = options.u || 'root';
  const currentUser = env.effectiveUser;

  if (flags.k) {
    useUbuntuAuthStore.getState().revokeSudoAccess('global-window');
    if (positional.length === 0) return 0;
  }

  if (flags.K) {
    useUbuntuAuthStore.getState().revokeSudoAccess('global-window');
    return 0;
  }

  if (flags.l) {
    return await handleSudoList(currentUser, streams);
  }

  if (positional.length === 0 && !flags.i) {
    streams.stderr.writeLine('usage: sudo [-u user] [-k] [-l] command [args...]');
    return 1;
  }

  if (flags.i) {
    return await handleSudoShell(currentUser, targetUser, env, streams);
  }

  const commandName = positional[0];
  const authResult = await checkSudoAuthorization({
    requestingUser: currentUser,
    targetUser,
    command: commandName,
  });

  if (!authResult.authorized) {
    const errStr = authResult.error || `${currentUser} is not in the sudoers file. This incident will be reported.`;
    streams.stderr.writeLine(errStr);
    return 1;
  }

  if (authResult.requiresPassword && !isSudoCached('global-window')) {
    streams.stdout.writeLine(`[sudo] password for ${currentUser}: `);
  }

  return await executeSudoCommand(positional, env, streams);
};

export async function executeSudoCommand(
  commandParts: string[],
  env: any,
  streams: any
): Promise<number> {
  const commandName = commandParts[0];
  const commandArgs = commandParts.slice(1);

  const builtIns = ['cd', 'pwd', 'history', 'help', 'exit'];
  if (builtIns.includes(commandName)) {
    const lines = [
      `sudo: ${commandName}: command not found`,
      `sudo: "${commandName}" is a shell built-in command, it cannot be run directly.`,
    ];
    lines.forEach(l => streams.stderr.writeLine(l));
    return 1;
  }

  const handler = commandRegistry[commandName];
  if (!handler) {
    streams.stderr.writeLine(`sudo: ${commandName}: command not found`);
    return 1;
  }

  return await withElevation(async () => await handler(commandArgs, env, streams)) ?? 0;
}

async function handleSudoList(username: string, streams: any): Promise<number> {
  const authResult = await checkSudoAuthorization({ requestingUser: username });
  if (!authResult.authorized) {
    streams.stderr.writeLine(`Sorry, user ${username} may not run sudo on ubuntu-web.`);
    return 1;
  }

  streams.stdout.writeLine(`Matching Defaults entries for ${username} on ubuntu-web:`);
  streams.stdout.writeLine('    env_reset, mail_badpass,');
  streams.stdout.writeLine('    secure_path=/usr/local/sbin\\:/usr/local/bin\\:/usr/sbin\\:/usr/bin\\:/sbin\\:/bin');
  streams.stdout.writeLine('');
  streams.stdout.writeLine(`User ${username} may run the following commands on ubuntu-web:`);
  streams.stdout.writeLine('    (ALL : ALL) ALL');
  return 0;
}

async function handleSudoShell(currentUser: string, targetUser: string, env: any, streams: any): Promise<number> {
  const authResult = await checkSudoAuthorization({ requestingUser: currentUser, targetUser });
  if (!authResult.authorized) {
    streams.stderr.writeLine(authResult.error || `${currentUser} is not in the sudoers file.`);
    return 1;
  }

  env.pushUser(targetUser);
  return 0;
}

import type { CommandHandler } from './types';
import { getAbsolutePathAsync, resolveRelativePathAsync } from '../../../fs/pathResolver';
import { stat } from '../../../fs/operations';

export const testCmd: CommandHandler = async (args, env, _streams) => {
  // If invoked as [, the last argument must be ]
  if (args.length > 0 && args[args.length - 1] === ']') {
    args = args.slice(0, -1);
  }

  if (args.length === 0) return 1;

  // Simple recursive evaluator for logical operators -a and -o and !
  const evaluate = async (tokens: string[]): Promise<boolean> => {
    if (tokens.length === 0) return false;

    // NOT operator
    if (tokens[0] === '!') {
      return !(await evaluate(tokens.slice(1)));
    }

    // Find highest precedence operator: -o (OR), then -a (AND)
    // Actually, -a has higher precedence than -o in POSIX test
    let orIdx = tokens.indexOf('-o');
    if (orIdx !== -1) {
      const left = await evaluate(tokens.slice(0, orIdx));
      if (left) return true;
      return await evaluate(tokens.slice(orIdx + 1));
    }

    let andIdx = tokens.indexOf('-a');
    if (andIdx !== -1) {
      const left = await evaluate(tokens.slice(0, andIdx));
      if (!left) return false;
      return await evaluate(tokens.slice(andIdx + 1));
    }

    // Unary operators
    if (tokens.length === 2) {
      const op = tokens[0];
      const val = tokens[1];

      if (op === '-z') return val === '';
      if (op === '-n') return val !== '';

      // File tests
      if (['-e', '-f', '-d', '-r', '-w', '-x', '-s'].includes(op)) {
        try {
          const cwdAbs = await getAbsolutePathAsync(env.cwdId);
          const node = await resolveRelativePathAsync(cwdAbs, val);
          if (!node) return false;

          if (op === '-e') return true;
          if (op === '-d') return node.type === 'directory';
          if (op === '-f') return node.type === 'file';

          // Basic mock permissions
          if (op === '-r' || op === '-w' || op === '-x') return true; 

          if (op === '-s') {
            if (node.type !== 'file') return false;
            const absPath = await getAbsolutePathAsync(node.id);
            const st = await stat(absPath);
            return st.sizeBytes > 0;
          }
        } catch {
          return false;
        }
      }
      return false;
    }

    // Binary operators
    if (tokens.length === 3) {
      const left = tokens[0];
      const op = tokens[1];
      const right = tokens[2];

      if (op === '=') return left === right;
      if (op === '!=') return left !== right;

      const lInt = parseInt(left, 10);
      const rInt = parseInt(right, 10);

      if (op === '-eq') return lInt === rInt;
      if (op === '-ne') return lInt !== rInt;
      if (op === '-lt') return lInt < rInt;
      if (op === '-gt') return lInt > rInt;
      if (op === '-le') return lInt <= rInt;
      if (op === '-ge') return lInt >= rInt;

      return false;
    }

    // Single token evaluates to true if non-empty
    if (tokens.length === 1) {
      return tokens[0] !== '';
    }

    return false;
  };

  const result = await evaluate(args);
  return result ? 0 : 1;
};

import type { CommandHandler } from './types';
import { parseArgs } from '../commandParser';

export const grep: CommandHandler = async (args, env, streams) => {
  const { flags, positional } = parseArgs(args);

  if (positional.length < 1) {
    ['grep: missing pattern'].forEach((line: string) => streams.stderr.writeLine(line)); return 1;
  }

  const pattern = positional[0];
  const targets = positional.slice(1);
  let regex: RegExp;
  try {
    regex = new RegExp(pattern, flags.i ? 'i' : '');
  } catch {
    [`grep: invalid pattern: '${pattern}'`].forEach((line: string) => streams.stderr.writeLine(line)); return 1;
  }

  interface FileEntry { name: string; content: string; }
  const files: FileEntry[] = [];

  if (!flags.r && targets.length === 0) {
    files.push({ name: '(standard input)', content: streams.stdin.readAll() });
  } else {
    const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
    const { stat, readdir, readFile } = await import('../../../fs/operations');
    const cwdPath = await getAbsolutePathAsync(env.cwdId);

    if (flags.r) {
      const startPath = targets.length > 0 ? targets[0] : '.';
      const startNode = await resolveRelativePathAsync(cwdPath, startPath);
      if (!startNode) {
        [`grep: ${startPath}: No such file or directory`].forEach((line: string) => streams.stderr.writeLine(line)); return 1;
      }

      const startAbsPath = await getAbsolutePathAsync(startNode.id);
      if (startNode.type === 'file') {
        const text = await (await readFile(startAbsPath)).text();
        files.push({ name: startPath, content: text });
      } else {
        async function walkTreeAsync(currentId: string, currentPath: string) {
          const absPath = await getAbsolutePathAsync(currentId);
          const node = await stat(absPath);
          if (node.type === 'file') {
            const text = await (await readFile(absPath)).text();
            files.push({ name: currentPath, content: text });
          } else if (node.type === 'directory') {
            const children = await readdir(absPath);
            for (const child of children) {
              await walkTreeAsync(child.id, currentPath === '.' ? child.name : currentPath + '/' + child.name);
            }
          }
        }
        await walkTreeAsync(startNode.id, startPath);
      }
    } else {
      for (const target of targets) {
        const node = await resolveRelativePathAsync(cwdPath, target);
        if (!node) {
          [`grep: ${target}: No such file or directory`].forEach((line: string) => streams.stderr.writeLine(line)); return 1;
        }
        if (node.type === 'directory') {
          [`grep: ${target}: Is a directory`].forEach((line: string) => streams.stderr.writeLine(line)); return 1;
        }
        const absPath = await getAbsolutePathAsync(node.id);
        const text = await (await readFile(absPath)).text();
        files.push({ name: target, content: text });
      }
    }
  }

  if (files.length === 0) {
    return 0;
  }

  const multiFile = files.length > 1;
  const outputLines: string[] = [];

  for (const file of files) {
    const lines = file.content.split('\n');
    let count = 0;
    for (let lineIdx = 0; lineIdx < lines.length; lineIdx++) {
      const line = lines[lineIdx];
      const matches = regex.test(line);
      const show = flags.v ? !matches : matches;
      if (show) {
        count++;
        if (!flags.c) {
          let result = '';
          if (multiFile && file.name !== '(standard input)') result += `\x1b[35m${file.name}\x1b[36m:\x1b[0m`;
          if (flags.n) result += `\x1b[32m${lineIdx + 1}\x1b[36m:\x1b[0m`;

          const highlighted = line.replace(regex, (match) => `\x1b[1;31m${match}\x1b[0m`);
          result += highlighted;
          outputLines.push(result);
        }
      }
    }
    if (flags.c) {
      if (multiFile && file.name !== '(standard input)') outputLines.push(`${file.name}:${count}`);
      else outputLines.push(`${count}`);
    }
  }

  outputLines.forEach((line: string) => streams.stdout.writeLine(line));
  return outputLines.length > 0 ? 0 : 1;
};

export const head: CommandHandler = async (args, env, streams) => {
  const { options, positional } = parseArgs(args, ['n']);

  const n = parseInt(options.n || '10', 10);
  if (isNaN(n) || n < 0) {
    [`head: invalid number of lines: '${options.n}'`].forEach((line: string) => streams.stderr.writeLine(line)); return 1;
  }

  const results: string[] = [];

  if (positional.length === 0) {
    const text = streams.stdin.readAll();
    const lines = text.split('\n').slice(0, n);
    results.push(...lines);
  } else {
    const multiFile = positional.length > 1;

    const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
    const { readFile } = await import('../../../fs/operations');
    const cwdPath = await getAbsolutePathAsync(env.cwdId);

    for (let i = 0; i < positional.length; i++) {
      const target = positional[i];
      const node = await resolveRelativePathAsync(cwdPath, target);

      if (!node) {
        [`head: ${target}: No such file or directory`].forEach((line: string) => streams.stderr.writeLine(line)); return 1;
      }
      if (node.type === 'directory') {
        [`head: ${target}: Is a directory`].forEach((line: string) => streams.stderr.writeLine(line)); return 1;
      }

      if (multiFile) {
        if (i > 0) results.push(''); 
        results.push(`==> ${target} <==`);
      }

      const absPath = await getAbsolutePathAsync(node.id);
      const text = await (await readFile(absPath)).text();
      const lines = text.split('\n').slice(0, n);
      results.push(...lines);
    }
  }

  results.forEach((line: string) => streams.stdout.writeLine(line)); return 0;
};

