export const wc: CommandHandler = async (args, env, streams) => {
  const { flags, positional } = parseArgs(args);

  const showAll = !flags.l && !flags.w && !flags.c;
  const results: string[] = [];
  let totalLines = 0;
  let totalWords = 0;
  let totalChars = 0;

  if (positional.length === 0) {
    const content = streams.stdin.readAll();
    const lines = content.split('\n').length;
    const words = content.trim().length === 0 ? 0 : content.trim().split(/\s+/).length;
    const chars = content.length;

    const parts: string[] = [];
    if (showAll || flags.l) parts.push(lines.toString().padStart(7, ' '));
    if (showAll || flags.w) parts.push(words.toString().padStart(7, ' '));
    if (showAll || flags.c) parts.push(chars.toString().padStart(7, ' '));
    results.push(parts.join(''));
  } else {
    const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
    const { readFile } = await import('../../../fs/operations');
    const cwdPath = await getAbsolutePathAsync(env.cwdId);

    for (const target of positional) {
      const node = await resolveRelativePathAsync(cwdPath, target);

      if (!node) {
        [`wc: ${target}: No such file or directory`].forEach((line: string) => streams.stderr.writeLine(line)); return 1;
      }
      if (node.type === 'directory') {
        [`wc: ${target}: Is a directory`].forEach((line: string) => streams.stderr.writeLine(line)); return 1;
      }

      const absPath = await getAbsolutePathAsync(node.id);
      const content = await (await readFile(absPath)).text();
      const lines = content.split('\n').length;
      const words = content.trim().length === 0 ? 0 : content.trim().split(/\s+/).length;
      const chars = content.length;

      totalLines += lines;
      totalWords += words;
      totalChars += chars;

      const parts: string[] = [];
      if (showAll || flags.l) parts.push(lines.toString().padStart(7, ' '));
      if (showAll || flags.w) parts.push(words.toString().padStart(7, ' '));
      if (showAll || flags.c) parts.push(chars.toString().padStart(7, ' '));
      parts.push(` ${target}`);

      results.push(parts.join(''));
    }

    if (positional.length > 1) {
      const parts: string[] = [];
      if (showAll || flags.l) parts.push(totalLines.toString().padStart(7, ' '));
      if (showAll || flags.w) parts.push(totalWords.toString().padStart(7, ' '));
      if (showAll || flags.c) parts.push(totalChars.toString().padStart(7, ' '));
      parts.push(' total');
      results.push(parts.join(''));
    }
  }

  results.forEach((line: string) => streams.stdout.writeLine(line)); return 0;
};


export const sort: CommandHandler = async (args, env, streams) => {
  const { flags, options, positional } = parseArgs(args, ['k']);

  let allLines: string[] = [];

  if (positional.length === 0) {
    const content = streams.stdin.readAll();
    allLines = content.split('\n');
    if (allLines.length > 0 && allLines[allLines.length - 1] === '') {
      allLines.pop();
    }
  } else {
    const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
    const { readFile } = await import('../../../fs/operations');
    const cwdPath = await getAbsolutePathAsync(env.cwdId);

    for (const target of positional) {
      const node = await resolveRelativePathAsync(cwdPath, target);
      if (!node) {
        streams.stderr.writeLine(`sort: cannot read: ${target}: No such file or directory`);
        return 1;
      }
      const absPath = await getAbsolutePathAsync(node.id);
      const content = await (await readFile(absPath)).text();
      const lines = content.split('\n');
      if (lines.length > 0 && lines[lines.length - 1] === '') {
        lines.pop();
      }
      allLines.push(...lines);
    }
  }

  const k = parseInt(options.k || '1', 10) - 1;
  const numeric = !!flags.n;
  const reverse = !!flags.r;
  const unique = !!flags.u;

  allLines.sort((a, b) => {
    let valA = a;
    let valB = b;
    if (k >= 0) {
      valA = a.split(/\s+/)[k] || '';
      valB = b.split(/\s+/)[k] || '';
    }

    let cmp = 0;
    if (numeric) {
      const numA = parseFloat(valA);
      const numB = parseFloat(valB);
      if (!isNaN(numA) && !isNaN(numB)) {
        cmp = numA - numB;
      } else {
        cmp = valA.localeCompare(valB);
      }
    } else {
      cmp = valA.localeCompare(valB);
    }

    return reverse ? -cmp : cmp;
  });

  if (unique) {
    allLines = allLines.filter((line, i) => i === 0 || line !== allLines[i - 1]);
  }

  allLines.forEach(l => streams.stdout.writeLine(l));
  return 0;
};

export const uniq: CommandHandler = async (args, env, streams) => {
  const { flags, positional } = parseArgs(args);

  let lines: string[] = [];
  if (positional.length === 0) {
    const content = streams.stdin.readAll();
    lines = content.split('\n');
    if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop();
  } else {
    const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
    const { readFile } = await import('../../../fs/operations');
    const cwdPath = await getAbsolutePathAsync(env.cwdId);

    const node = await resolveRelativePathAsync(cwdPath, positional[0]);
    if (!node) {
      streams.stderr.writeLine(`uniq: ${positional[0]}: No such file or directory`);
      return 1;
    }
    const absPath = await getAbsolutePathAsync(node.id);
    const content = await (await readFile(absPath)).text();
    lines = content.split('\n');
    if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop();
  }

  let count = 0;
  let prevLine: string | null = null;

  const flush = () => {
    if (prevLine !== null) {
      if (flags.d && count === 1) return;
      if (flags.c) {
        streams.stdout.writeLine(`${count.toString().padStart(7, ' ')} ${prevLine}`);
      } else {
        streams.stdout.writeLine(prevLine);
      }
    }
  };

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (prevLine === null) {
      prevLine = line;
      count = 1;
    } else if (line === prevLine) {
      count++;
    } else {
      flush();
      prevLine = line;
      count = 1;
    }
  }
  flush();

  return 0;
};

export const cut: CommandHandler = async (args, env, streams) => {
  const { options, positional } = parseArgs(args, ['d', 'f']);

  if (!options.f) {
    streams.stderr.writeLine(`cut: you must specify a list of bytes, characters, or fields`);
    return 1;
  }

  const delimiter = options.d || '\t';
  const fields = options.f.split(',').flatMap(part => {
    if (part.includes('-')) {
      const [start, end] = part.split('-');
      const s = parseInt(start, 10);
      const e = parseInt(end, 10);
      if (!isNaN(s) && !isNaN(e)) {
        return Array.from({ length: e - s + 1 }, (_, i) => s + i);
      }
    }
    const val = parseInt(part, 10);
    return isNaN(val) ? [] : [val];
  }).map(n => n - 1);

  let lines: string[] = [];
  if (positional.length === 0) {
    const content = streams.stdin.readAll();
    lines = content.split('\n');
    if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop();
  } else {
    const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
    const { readFile } = await import('../../../fs/operations');
    const cwdPath = await getAbsolutePathAsync(env.cwdId);

    for (const target of positional) {
      const node = await resolveRelativePathAsync(cwdPath, target);
      if (!node) continue;
      const absPath = await getAbsolutePathAsync(node.id);
      const content = await (await readFile(absPath)).text();
      const fileLines = content.split('\n');
      if (fileLines.length > 0 && fileLines[fileLines.length - 1] === '') fileLines.pop();
      lines.push(...fileLines);
    }
  }

  for (const line of lines) {
    const parts = line.split(delimiter);
    const selected = fields.map(f => parts[f]).filter(p => p !== undefined);
    streams.stdout.writeLine(selected.join(delimiter));
  }

  return 0;
};

export const tr: CommandHandler = async (args, _env, streams) => {
  const { flags, positional } = parseArgs(args);

  if (positional.length < 1 && !flags.d && !flags.s) {
    streams.stderr.writeLine(`tr: missing operand`);
    return 1;
  }

  const set1 = positional[0] || '';
  const set2 = positional[1] || '';

  const content = streams.stdin.readAll();
  let result = content;

  // Simple range expansion (e.g. a-z)
  const expandSet = (s: string) => {
    let expanded = '';
    for (let i = 0; i < s.length; i++) {
      if (s[i + 1] === '-' && i + 2 < s.length) {
        const start = s.charCodeAt(i);
        const end = s.charCodeAt(i + 2);
        for (let j = start; j <= end; j++) expanded += String.fromCharCode(j);
        i += 2;
      } else {
        expanded += s[i];
      }
    }
    return expanded;
  };

  const exp1 = expandSet(set1);
  const exp2 = expandSet(set2);

  if (flags.d) {
    for (const char of exp1) {
      result = result.split(char).join('');
    }
  } else if (flags.s) {
    // Squeeze
    for (const char of exp1) {
      const regex = new RegExp(`[${char}]+`, 'g');
      result = result.replace(regex, char);
    }
  } else {
    // Translate
    let newStr = '';
    for (const char of result) {
      const idx = exp1.indexOf(char);
      if (idx !== -1) {
        newStr += exp2[Math.min(idx, exp2.length - 1)];
      } else {
        newStr += char;
      }
    }
    result = newStr;
  }

  streams.stdout.writeLine(result.replace(/\n$/, '')); // Avoid double newline if stream handles it
  return 0;
};

export const tee: CommandHandler = async (args, env, streams) => {
  const { flags, positional } = parseArgs(args);

  const content = streams.stdin.readAll();
  streams.stdout.writeLine(content.replace(/\n$/, ''));

  if (positional.length > 0) {
    const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
    const { writeFile } = await import('../../../fs/operations');
    const cwdPath = await getAbsolutePathAsync(env.cwdId);

    for (const target of positional) {
      let targetPath = '';
      const node = await resolveRelativePathAsync(cwdPath, target);
      if (node) {
        targetPath = await getAbsolutePathAsync(node.id);
      } else {
        const parts = target.split('/');
        const destName = parts.pop()!;
        const parentPath = parts.join('/') || '.';
        const parentNode = await resolveRelativePathAsync(cwdPath, parentPath);
        if (!parentNode) {
          streams.stderr.writeLine(`tee: ${target}: No such file or directory`);
          continue;
        }
        const parentAbs = await getAbsolutePathAsync(parentNode.id);
        targetPath = parentAbs === '/' ? '/' + destName : parentAbs + '/' + destName;
      }

      try {
        await writeFile(targetPath, content, { append: !!flags.a });
      } catch (err: any) {
        streams.stderr.writeLine(`tee: ${target}: Permission denied`);
      }
    }
  }

  return 0;
};

export const sed: CommandHandler = async (args, env, streams) => {
  const { flags, options, positional } = parseArgs(args, ['e']);

  let expression = options.e || positional.shift();
  if (!expression) {
    streams.stderr.writeLine(`sed: missing command`);
    return 1;
  }

  let regex: RegExp;
  let replacement = '';
  let global = false;

  if (expression.startsWith('s/')) {
    const delim = expression[1];
    const parts = expression.split(delim);
    if (parts.length >= 4) {
      let pattern = parts[1];
      replacement = parts[2];
      global = parts[3].includes('g');
      try {
        regex = new RegExp(pattern, global ? 'g' : '');
      } catch (e) {
        streams.stderr.writeLine(`sed: -e expression #1, char 0: invalid reference`);
        return 1;
      }
    } else {
      streams.stderr.writeLine(`sed: -e expression #1, char 0: unterminated 's' command`);
      return 1;
    }
  } else {
    streams.stderr.writeLine(`sed: only 's///' commands are supported for now`);
    return 1;
  }

  if (positional.length === 0) {
    const content = streams.stdin.readAll();
    const lines = content.split('\n');
    for (let i = 0; i < lines.length; i++) {
      let l = lines[i];
      if (i === lines.length - 1 && l === '') break;
      streams.stdout.writeLine(l.replace(regex, replacement));
    }
  } else {
    const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
    const { readFile, writeFile } = await import('../../../fs/operations');
    const cwdPath = await getAbsolutePathAsync(env.cwdId);

    for (const target of positional) {
      const node = await resolveRelativePathAsync(cwdPath, target);
      if (!node) {
        streams.stderr.writeLine(`sed: can't read ${target}: No such file or directory`);
        continue;
      }
      const absPath = await getAbsolutePathAsync(node.id);
      const content = await (await readFile(absPath)).text();
      const lines = content.split('\n');

      let newContent = '';
      for (let i = 0; i < lines.length; i++) {
        let l = lines[i];
        if (i === lines.length - 1 && l === '') break;
        newContent += l.replace(regex, replacement) + '\n';
      }

      if (flags.i) {
        await writeFile(absPath, newContent);
      } else {
        streams.stdout.writeLine(newContent.replace(/\n$/, ''));
      }
    }
  }

  return 0;
};

export const awk: CommandHandler = async (args, env, streams) => {
  const { positional } = parseArgs(args);

  const program = positional.shift();
  if (!program) {
    streams.stderr.writeLine(`awk: missing program`);
    return 1;
  }

  const printMatch = program.match(/\{\s*print\s+(.*?)\s*\}/);
  if (!printMatch) {
    streams.stderr.writeLine(`awk: only {print ...} supported`);
    return 1;
  }

  const fields = printMatch[1].split(',').map(s => s.trim());

  let lines: string[] = [];
  if (positional.length === 0) {
    const content = streams.stdin.readAll();
    lines = content.split('\n');
    if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop();
  } else {
    const { getAbsolutePathAsync, resolveRelativePathAsync } = await import('../../../fs/pathResolver');
    const { readFile } = await import('../../../fs/operations');
    const cwdPath = await getAbsolutePathAsync(env.cwdId);

    for (const target of positional) {
      const node = await resolveRelativePathAsync(cwdPath, target);
      if (!node) continue;
      const absPath = await getAbsolutePathAsync(node.id);
      const content = await (await readFile(absPath)).text();
      const fileLines = content.split('\n');
      if (fileLines.length > 0 && fileLines[fileLines.length - 1] === '') fileLines.pop();
      lines.push(...fileLines);
    }
  }

  let nr = 0;
  for (const line of lines) {
    nr++;
    const parts = line.split(/\s+/).filter(Boolean);
    const nf = parts.length;

    const output = fields.map(f => {
      if (f === 'NR') return nr;
      if (f === 'NF') return nf;
      if (f === '$0') return line;
      if (f.startsWith('$')) {
        const idx = parseInt(f.slice(1), 10) - 1;
        return parts[idx] || '';
      }
      return f.replace(/^["']|["']$/g, '');
    }).join(' ');

    streams.stdout.writeLine(output);
  }

  return 0;
};

import type { CommandHandler } from './types';
import { getAuthContext } from '../../../store/useUbuntuVFSStore';
// import removed: useUbuntuVFSStore
import { getUserGroups } from '../../../services/sudoersParser';

/**
 * id — Print real and effective user and group IDs.
 *
 * Usage:
 *   id                Print current user's info
 *   id <username>     Print specific user's info
 *
 * Output format (matches real Linux):
 *   uid=1000(user) gid=1000(user) groups=1000(user),4(admin),27(sudo)
 */
export const id: CommandHandler = async (args, env, streams) => {
  const targetUser = args[0] || env?.effectiveUser || getAuthContext().username;

  const { readFile } = await import('../../../fs/operations');
  let passwdContent = '';
  try {
    const blob = await readFile('/etc/passwd');
    passwdContent = await blob.text();
  } catch (e) {
    [`uid=1000(${targetUser}) gid=1000(${targetUser}) groups=1000(${targetUser})`].forEach((line: string) => streams.stdout.writeLine(line)); return 0;
  }

  const lines = passwdContent.split('\n');
  const userLine = lines.find(l => l.startsWith(targetUser + ':'));

  if (!userLine) {
    [`id: '${targetUser}': no such user`].forEach((line: string) => streams.stderr.writeLine(line)); return 1;
  }

  const parts = userLine.split(':');
  const uid = parts[2];
  const gid = parts[3];

  const groups = await getUserGroups(targetUser);

  let groupContent = '';
  try {
    const groupBlob = await readFile('/etc/group');
    groupContent = await groupBlob.text();
  } catch (e) {}

  const groupStr = groups.map((g, i) => {
    if (groupContent) {
      const groupLines = groupContent.split('\n');
      const groupLine = groupLines.find(l => l.startsWith(g + ':'));
      if (groupLine) {
        const groupGid = groupLine.split(':')[2];
        return `${groupGid}(${g})`;
      }
    }
    return `${1000 + i}(${g})`;
  }).join(',');

  [`uid=${uid}(${targetUser}) gid=${gid}(${targetUser}) groups=${groupStr}`].forEach((line: string) => streams.stdout.writeLine(line)); return 0;
};

/**
 * groups — Print group memberships for a user.
 *
 * Usage:
 *   groups              Print current user's groups
 *   groups <username>    Print specific user's groups
 */
export const groups: CommandHandler = async (args, env, streams) => {
  const targetUser = args[0] || env?.effectiveUser || getAuthContext().username;
  const userGroups = await getUserGroups(targetUser);

  if (userGroups.length === 0) {
    [targetUser].forEach((line: string) => streams.stdout.writeLine(line)); return 0;
  }

  [`${targetUser} : ${userGroups.join(' ')}`].forEach((line: string) => streams.stdout.writeLine(line)); return 0;
};

/**
 * passwd — Change user password.
 *
 * Usage:
 *   passwd              Change own password
 *   passwd <username>    Change another user's password (root only)
 *
 * NOTE: This is a simplified simulation. In real Linux, passwd is interactive
 * (prompts for old password, new password, confirm). For our simulation,
 * we output educational information about what would happen.
 */
export const passwd: CommandHandler = (args, env, streams) => {
  const username = env?.effectiveUser || getAuthContext().username;
  const targetUser = args[0] || username;

  if (targetUser !== username && username !== 'root') {
    ['passwd: You may not view or modify password information for other users.'].forEach((line: string) => streams.stderr.writeLine(line)); return 1;
  }

  [`passwd: Changing password for ${targetUser}.`].forEach((line: string) => streams.stdout.writeLine(line));
  [`(interactive password change not supported in this version)`].forEach((line: string) => streams.stdout.writeLine(line));

  return 0;
};

/**
 * adduser — Add a new user (root only).
 *
 * Usage:
 *   adduser <username>
 *
 * Educational output showing what would happen.
 */
export const adduser: CommandHandler = (args, env, streams) => {
  const username = env?.effectiveUser || getAuthContext().username;

  if (username !== 'root') {
    ['adduser: Only root may add a user or group to the system.'].forEach((line: string) => streams.stderr.writeLine(line)); return 1;
  }

  if (args.length === 0) {
    ['adduser: Only one or two names allowed.'].forEach((line: string) => streams.stderr.writeLine(line)); return 1;
  }

  const newUser = args[0];

  [
    `Adding user '${newUser}' ...`,
    `Adding new group '${newUser}' (1002) ...`,
    `Adding new user '${newUser}' (1002) with group '${newUser}' ...`,
    `Creating home directory '/home/${newUser}' ...`,
    `Copying files from '/etc/skel' ...`,
    '',
    '(interactive user creation not yet fully implemented)',
    '',
    'In a real Linux system, this would also:',
    '  1. Prompt for a password for the new user',
    '  2. Ask for full name, room number, etc. (GECOS fields)',
    '  3. Create the home directory with default files',
    '  4. Add entries to /etc/passwd, /etc/shadow, /etc/group',
  ].forEach((line: string) => streams.stdout.writeLine(line)); return 0;
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import * as fs from '../../../fs/operations';

interface NanoEditorProps {
  fileId: string;
  onExit: () => void;
}

export function NanoEditor({ fileId, onExit }: NanoEditorProps) {
  const [buffer, setBuffer] = useState('');
  const [fileName, setFileName] = useState('');
  const [filePath, setFilePath] = useState('');
  const [modified, setModified] = useState(false);
  const [message, setMessage] = useState('');
  const [confirmExit, setConfirmExit] = useState(false);
  const [loading, setLoading] = useState(true);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const originalContent = useRef('');

  useEffect(() => {
    let isMounted = true;
    async function loadFile() {
      try {
        const { getDB } = await import('../../../fs/db');
        const db = await getDB();
        const node = await db.get('inodes', fileId);
        if (node && isMounted) {
          setFileName(node.name);
          const { getAbsolutePathAsync } = await import('../../../fs/pathResolver');
          const path = await getAbsolutePathAsync(node.id);
          setFilePath(path);

          const blob = await fs.readFile(path);
          const text = await blob.text();
          if (isMounted) {
            setBuffer(text);
            originalContent.current = text;
          }
        }
      } catch (err) {
        console.error(err);
      } finally {
        if (isMounted) setLoading(false);
      }
    }
    loadFile();
    return () => { isMounted = false; };
  }, [fileId]);

  useEffect(() => {
    if (!loading) {
      textareaRef.current?.focus();
    }
  }, [loading]);

  const handleChange = useCallback((e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newContent = e.target.value;
    setBuffer(newContent);
    setModified(newContent !== originalContent.current);
    if (confirmExit) setConfirmExit(false);
  }, [confirmExit]);

  const showMessage = useCallback((msg: string, duration = 3000) => {
    setMessage(msg);
    setTimeout(() => setMessage(''), duration);
  }, []);

  const saveBuffer = useCallback(async () => {
    if (!filePath) return;
    try {
      await fs.writeFile(filePath, buffer);
      const lineCount = buffer.split('\n').length;
      showMessage(`[ Wrote ${lineCount} lines ]`);
      setModified(false);
      originalContent.current = buffer;
    } catch (err) {
      showMessage(`[ Error writing file ]`);
    }
  }, [buffer, filePath, showMessage]);

  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (confirmExit) {
      e.preventDefault();
      if (e.key === 'y' || e.key === 'Y') {
        saveBuffer().then(onExit);
      } else if (e.key === 'n' || e.key === 'N' || e.key === 'Enter') {
        onExit();
      } else if (e.key === 'Escape') {
        setConfirmExit(false);
        setMessage('');
      }
      return;
    }

    if (e.ctrlKey) {
      switch (e.key.toLowerCase()) {
        case 'o':
        case 's':
          e.preventDefault();
          saveBuffer();
          break;
        case 'x':
          e.preventDefault();
          if (modified) {
            setConfirmExit(true);
            setMessage('Save modified buffer? (y/N)');
          } else {
            onExit();
          }
          break;
        case 'g':
        case 'w':
        case 'k':
        case 'u':
        case 'j':
        case 'r':
        case '\\':
        case 't':
        case 'c':
        case '_':
          e.preventDefault();
          break;
        default:
          e.preventDefault();
          break;
      }
    }
  }, [confirmExit, modified, saveBuffer, onExit]);

  if (loading) return null;

  const displayName = modified ? `${fileName} (modified)` : fileName;

  return (
    <div className="nano-container">
      <div className="nano-title-bar">
        GNU nano 7.2&nbsp;&nbsp;&nbsp;&nbsp;{displayName}
      </div>
      <textarea
        ref={textareaRef}
        className="nano-editor"
        value={buffer}
        onChange={handleChange}
        onKeyDown={handleKeyDown}
        spellCheck={false}
        autoCapitalize="off"
        autoCorrect="off"
      />
      <div className="nano-status-line">{message}</div>
      <div className="nano-shortcut-bar">
        <span><span className="nano-shortcut-key">^G</span> Help</span>
        <span><span className="nano-shortcut-key">^O</span> Write Out</span>
        <span><span className="nano-shortcut-key">^W</span> Where Is</span>
        <span><span className="nano-shortcut-key">^K</span> Cut</span>
        <span><span className="nano-shortcut-key">^U</span> Paste</span>
        <span><span className="nano-shortcut-key">^J</span> Justify</span>
        <span><span className="nano-shortcut-key">^X</span> Exit</span>
        <span><span className="nano-shortcut-key">^R</span> Read File</span>
        <span><span className="nano-shortcut-key">^\\</span> Replace</span>
        <span><span className="nano-shortcut-key">^T</span> Execute</span>
        <span><span className="nano-shortcut-key">^C</span> Location</span>
        <span><span className="nano-shortcut-key">^_</span> Go To Line</span>
      </div>
    </div>
  );
}

import React, { useEffect, useRef } from 'react';
import { LucideMinus, LucidePlus, LucideCheck } from 'lucide-react';
import { useTerminalProfileStore } from '../store/useTerminalProfileStore';
import { useWindowStore } from '../../../store';

interface TerminalMenuProps {
  windowId: string;
  onClose: () => void;
}

export const TerminalMenu: React.FC<TerminalMenuProps> = ({ windowId, onClose }) => {
  const menuRef = useRef<HTMLDivElement>(null);
  const profile = useTerminalProfileStore(state => state.activeProfile);
  const updateProfile = useTerminalProfileStore(state => state.updateProfile);
  const openWindow = useWindowStore((state: any) => state.openWindow);

  // Close when clicking outside
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        onClose();
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [onClose]);

  const handleZoomOut = () => {
    if (profile.fontSize > 8) updateProfile({ fontSize: profile.fontSize - 1 });
  };
  const handleZoomReset = () => {
    updateProfile({ fontSize: 14 }); // Default
  };
  const handleZoomIn = () => {
    if (profile.fontSize < 36) updateProfile({ fontSize: profile.fontSize + 1 });
  };

  const handleAction = (action: string) => {
    switch (action) {
      case 'new-tab':
        window.dispatchEvent(new CustomEvent('terminal:new-tab', { detail: { windowId } }));
        break;
      case 'new-window':
        openWindow('terminal');
        break;
      case 'show-open-tabs':
        // Optional feature
        break;
      case 'fullscreen':
        window.dispatchEvent(new CustomEvent('terminal:fullscreen', { detail: { windowId } }));
        break;
      case 'preferences':
        openWindow('terminal-preferences');
        break;
      case 'keyboard-shortcuts':
        // Optional feature
        break;
      case 'about':
        window.dispatchEvent(new CustomEvent('terminal:about', { detail: { windowId } }));
        break;
    }
    onClose();
  };

  // Determine effective theme state (mapping for simplicity)
  const isSystem = profile.colorScheme === 'ubuntu';
  const isLight = profile.colorScheme === 'ubuntuLight';
  const isDark = profile.colorScheme === 'vscode';

  return (
    <div className="terminal-menu-popup" ref={menuRef} onDoubleClick={(e) => e.stopPropagation()}>
      <div className="terminal-menu-pointer" />

      {/* Themes */}
      <div className="terminal-menu-section terminal-menu-themes">
        <button 
          className={`terminal-theme-btn terminal-theme-system ${isSystem ? 'active' : ''}`}
          onClick={() => updateProfile({ colorScheme: 'ubuntu' })}
          title="System Theme"
        >
          <div className="terminal-theme-circle" />
          {isSystem && <div className="terminal-theme-check"><LucideCheck size={10} /></div>}
        </button>
        <button 
          className={`terminal-theme-btn terminal-theme-light ${isLight ? 'active' : ''}`}
          onClick={() => updateProfile({ colorScheme: 'ubuntuLight' })}
          title="Light Theme"
        >
          <div className="terminal-theme-circle" />
          {isLight && <div className="terminal-theme-check"><LucideCheck size={10} /></div>}
        </button>
        <button 
          className={`terminal-theme-btn terminal-theme-dark ${isDark ? 'active' : ''}`}
          onClick={() => updateProfile({ colorScheme: 'vscode' })}
          title="Dark Theme"
        >
          <div className="terminal-theme-circle" />
          {isDark && <div className="terminal-theme-check"><LucideCheck size={10} /></div>}
        </button>
      </div>

      <div className="terminal-menu-divider" />

      {/* Zoom */}
      <div className="terminal-menu-section terminal-menu-zoom">
        <button className="terminal-zoom-btn" onClick={handleZoomOut}><LucideMinus size={14} /></button>
        <button className="terminal-zoom-reset" onClick={handleZoomReset}>
          {Math.round((profile.fontSize / 14) * 100)}%
        </button>
        <button className="terminal-zoom-btn" onClick={handleZoomIn}><LucidePlus size={14} /></button>
      </div>

      <div className="terminal-menu-divider" />

      {/* Actions */}
      <div className="terminal-menu-list">
        <button className="terminal-menu-item" onClick={() => handleAction('new-tab')}>
          <span>New Tab</span>
          <span className="terminal-menu-shortcut">Shift+Ctrl+T</span>
        </button>
        <button className="terminal-menu-item" onClick={() => handleAction('new-window')}>
          <span>New Window</span>
          <span className="terminal-menu-shortcut">Shift+Ctrl+N</span>
        </button>
        <div className="terminal-menu-divider" />
        <button className="terminal-menu-item" onClick={() => handleAction('show-open-tabs')}>
          <span>Show Open Tabs</span>
          <span className="terminal-menu-shortcut">Shift+Ctrl+O</span>
        </button>
        <div className="terminal-menu-divider" />
        <button className="terminal-menu-item" onClick={() => handleAction('fullscreen')}>
          <span>Fullscreen</span>
          <span className="terminal-menu-shortcut">F11</span>
        </button>
        <div className="terminal-menu-divider" />
        <button className="terminal-menu-item" onClick={() => handleAction('preferences')}>
          <span>Preferences</span>
          <span className="terminal-menu-shortcut">Ctrl+,</span>
        </button>
        <button className="terminal-menu-item" onClick={() => handleAction('keyboard-shortcuts')}>
          <span>Keyboard Shortcuts</span>
          <span className="terminal-menu-shortcut">Ctrl+?</span>
        </button>
        <button className="terminal-menu-item" onClick={() => handleAction('about')}>
          <span>About</span>
        </button>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect, type KeyboardEvent } from 'react';
import { LucideSearch, LucideChevronUp, LucideChevronDown, LucideSettings, LucideX } from 'lucide-react';

interface TerminalSearchProps {
  windowId: string;
  onClose: () => void;
}

export const TerminalSearch: React.FC<TerminalSearchProps> = ({ windowId, onClose }) => {
  const [query, setQuery] = useState('');
  const [matchCase, setMatchCase] = useState(false);
  const [wholeWord, setWholeWord] = useState(false);
  const [useRegex, setUseRegex] = useState(false);
  const [settingsOpen, setSettingsOpen] = useState(false);

  const inputRef = useRef<HTMLInputElement>(null);
  const settingsRef = useRef<HTMLDivElement>(null);

  const [resultIndex, setResultIndex] = useState(-1);
  const [resultCount, setResultCount] = useState(0);

  useEffect(() => {
    const handleResults = (e: any) => {
      if (e.detail) {
        setResultIndex(e.detail.resultIndex);
        setResultCount(e.detail.resultCount);
      }
    };
    window.addEventListener('terminal:search-results', handleResults);
    return () => window.removeEventListener('terminal:search-results', handleResults);
  }, []);

  useEffect(() => {
    // Focus the input when opened
    inputRef.current?.focus();
  }, []);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (settingsRef.current && !settingsRef.current.contains(e.target as Node)) {
        setSettingsOpen(false);
      }
    };
    if (settingsOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [settingsOpen]);

  const dispatchSearch = (direction: 'next' | 'prev') => {
    if (!query) return;

    window.dispatchEvent(new CustomEvent('terminal:do-search', {
      detail: {
        windowId,
        query,
        options: {
          matchCase,
          wholeWord,
          regex: useRegex,
          incremental: false,
        },
        direction
      }
    }));
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      if (e.shiftKey) {
        dispatchSearch('prev');
      } else {
        dispatchSearch('next');
      }
    } else if (e.key === 'Escape') {
      onClose();
      e.stopPropagation();
      e.preventDefault();
    }
  };

  // Perform incremental search as user types
  useEffect(() => {
    if (query) {
      window.dispatchEvent(new CustomEvent('terminal:do-search', {
        detail: {
          windowId,
          query,
          options: {
            matchCase,
            wholeWord,
            regex: useRegex,
            incremental: true,
          },
          direction: 'next'
        }
      }));
    } else {
      // Clear search
      window.dispatchEvent(new CustomEvent('terminal:close-search', { detail: { windowId } }));
    }
  }, [query, matchCase, wholeWord, useRegex, windowId]);

  return (
    <div className="terminal-search-bar">
      <div className="terminal-search-input-wrapper">
        <LucideSearch size={14} className="terminal-search-icon" />
        <input
          ref={inputRef}
          type="text"
          className="terminal-search-input"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="Find..."
        />
      </div>

      <div className="terminal-search-actions">
        {resultCount > 0 && <span className="terminal-search-count">{resultIndex >= 0 ? resultIndex + 1 : 0} of {resultCount}</span>}
        <button 
          className="terminal-search-btn" 
          onClick={() => dispatchSearch('prev')}
          title="Previous Match (Shift+Enter)"
        >
          <LucideChevronUp size={16} />
        </button>
        <button 
          className="terminal-search-btn" 
          onClick={() => dispatchSearch('next')}
          title="Next Match (Enter)"
        >
          <LucideChevronDown size={16} />
        </button>

        <div style={{ position: 'relative' }} ref={settingsRef}>
          <button 
            className={`terminal-search-btn ${settingsOpen ? 'active' : ''}`}
            onClick={() => setSettingsOpen(!settingsOpen)}
            title="Search Options"
          >
            <LucideSettings size={14} />
          </button>

          {settingsOpen && (
            <div className="terminal-search-settings-popup">
              <label className="terminal-search-option">
                <input 
                  type="checkbox" 
                  checked={matchCase} 
                  onChange={(e) => setMatchCase(e.target.checked)} 
                />
                Match Case
              </label>
              <label className="terminal-search-option">
                <input 
                  type="checkbox" 
                  checked={wholeWord} 
                  onChange={(e) => setWholeWord(e.target.checked)} 
                />
                Whole Words
              </label>
              <label className="terminal-search-option">
                <input 
                  type="checkbox" 
                  checked={useRegex} 
                  onChange={(e) => setUseRegex(e.target.checked)} 
                />
                Use Regular Expressions
              </label>
            </div>
          )}
        </div>

        <button className="terminal-search-btn" onClick={onClose} title="Close Search">
          <LucideX size={16} />
        </button>
      </div>
    </div>
  );
};

